/* MY BAC — bibliothèque pédagogique terminale. Contenus structurés pour révision ; les exemples sont des repères à contextualiser. */
const library = {};
function addCourse(subject,id,title,subtitle,intro,sections,notions,examples,sheet,quiz){
  library[subject+':'+id]={title,subtitle,intro,sections,notions,examples,sheet,quiz};
}
const q=(question,opts,answer,why)=>({q:question,opts,a:answer,why});

// HGGSP — six thèmes du programme de terminale
addCourse('hggsp','guerre-paix','Thème 2 — Faire la guerre, faire la paix','Formes de conflits et modes de résolution',
'La guerre est un phénomène politique et social qui évolue avec les sociétés, les techniques et les rapports de puissance. Les conflits contemporains mêlent parfois États, groupes armés et acteurs transnationaux. Faire la paix suppose de mettre fin aux combats, mais aussi de construire un ordre politique suffisamment légitime pour durer.',[
['1. Penser la guerre : de Clausewitz aux conflits contemporains',['Pour Carl von Clausewitz (1780-1831), la guerre est un acte de violence destiné à contraindre l’adversaire à exécuter notre volonté. Elle est la continuation de la politique par d’autres moyens : la guerre poursuit donc un objectif politique et ne se réduit pas aux combats.','La guerre réelle est toutefois soumise au « brouillard de la guerre » : informations incomplètes, incertitude, hasard, fatigue et réactions de l’adversaire. La guerre absolue est un modèle théorique d’escalade vers les extrêmes, rarement réalisé tel quel.','Les conflits contemporains ne sont pas tous des guerres interétatiques classiques. Ils peuvent opposer un État à un groupe armé, impliquer des milices, des sociétés militaires privées ou des réseaux transnationaux. Les acteurs irréguliers cherchent souvent à éviter l’affrontement symétrique et à user l’adversaire.']],
['2. Faire la paix : négocier, arbitrer, reconstruire',['La paix négative désigne l’absence de guerre ouverte ; la paix positive suppose aussi des institutions, des droits et des conditions politiques et sociales qui réduisent les risques de reprise des violences.','Les traités mettent formellement fin à une guerre, mais leur solidité dépend de leur acceptation, de leur mise en œuvre et de la capacité à traiter les causes du conflit. Une paix imposée peut nourrir le ressentiment.','La sécurité collective repose sur l’idée qu’une agression concerne l’ensemble de la communauté internationale. L’ONU, créée en 1945, peut autoriser des opérations de maintien ou d’imposition de la paix selon le cadre juridique et les décisions du Conseil de sécurité. La médiation, le désarmement, la justice transitionnelle et la reconstruction peuvent compléter les accords.']]
],[['Guerre','Affrontement armé organisé entre acteurs politiques, poursuivant des objectifs collectifs.'],['Guerre asymétrique','Conflit entre adversaires aux capacités et aux modes d’action très différents.'],['Guerre irrégulière','Conflit où au moins un acteur ne suit pas les formes classiques du combat entre armées régulières.'],['Paix négative','Absence de violence armée directe ou de guerre ouverte.'],['Paix positive','Ordre politique et social durable qui s’attaque aussi aux causes structurelles des violences.'],['Sécurité collective','Système dans lequel les États s’engagent à répondre collectivement aux menaces contre la paix.'],['Médiation','Intervention d’un tiers pour faciliter la négociation entre parties en conflit.']],
[['Clausewitz','De la guerre (ouvrage publié après sa mort, à partir de 1832) : la guerre est liée à une finalité politique.'],['ONU','Créée en 1945 : cadre central de la sécurité collective, avec des limites liées au droit de veto au Conseil de sécurité.'],['Guerre froide','Confrontation globale entre deux blocs, marquée par la dissuasion nucléaire et des conflits périphériques.'],['Conflits contemporains','Les guerres en Afghanistan, en Syrie ou en Ukraine illustrent des configurations différentes ; il faut distinguer leurs acteurs et leurs contextes.']],
[['Définir la guerre','Un affrontement armé organisé et politique, qui ne se confond pas avec toute violence.'],['Expliquer Clausewitz','La guerre poursuit un objectif politique et reste liée à la décision des autorités.'],['Caractériser les conflits actuels','Pluralité d’acteurs, asymétrie, internationalisation possible et brouillage entre civil et militaire.'],['Construire la paix','Cesser les combats, négocier, garantir les accords et traiter les causes de la reprise du conflit.']],
[q('Pour Clausewitz, la guerre est principalement…',['Une activité indépendante de la politique','La continuation de la politique par d’autres moyens','Un phénomène uniquement économique'],1,'Clausewitz relie la guerre à un objectif politique : elle n’est pas une violence sans finalité.'),q('Que désigne la paix positive ?',['La seule absence de combats','Un ordre durable qui réduit aussi les causes des violences','La victoire définitive d’un camp'],1,'La paix positive va au-delà du cessez-le-feu et implique des conditions de stabilité et de justice.')]);

addCourse('hggsp','memoire','Thème 3 — Histoire et mémoires','Histoire, mémoires et justice',
'L’histoire et la mémoire portent toutes deux sur le passé, mais elles n’ont ni le même objectif ni les mêmes méthodes. Les mémoires sont plurielles, vécues et parfois concurrentes ; l’histoire cherche à établir une connaissance critique à partir de sources. Les sociétés débattent de la transmission du passé, de la reconnaissance des victimes et de la justice.',[
['1. Histoire et mémoire : deux rapports au passé',['La mémoire est le rapport qu’un individu ou un groupe entretient avec son passé. Elle est sélective, affective, évolutive et liée à des identités collectives. Plusieurs mémoires d’un même événement peuvent coexister et entrer en concurrence.','L’histoire est une démarche de connaissance qui confronte les sources, contextualise les témoignages, vérifie les faits et soumet les interprétations à la critique. L’historien ne se contente pas de commémorer : il construit une explication argumentée et révisable.','Les témoignages sont des sources essentielles, mais ils doivent être contextualisés et croisés avec d’autres documents. Leur subjectivité n’annule pas leur valeur historique ; elle impose une méthode critique.']],
['2. Reconnaissance, justice et politiques mémorielles',['Les États organisent des commémorations, construisent des monuments, enseignent certains événements et peuvent reconnaître des responsabilités. Ces politiques mémorielles peuvent apaiser des conflits, mais aussi susciter des controverses lorsqu’elles imposent un récit officiel.','Après les violences de masse, la justice pénale internationale cherche à établir les responsabilités individuelles. Les tribunaux internationaux et les juridictions nationales contribuent à documenter les crimes, même si leurs moyens et leur compétence restent limités.','La justice transitionnelle associe, selon les contextes, procès, commissions vérité, réparations, réformes institutionnelles et dispositifs de mémoire. Elle cherche à articuler vérité, justice et réconciliation sans supposer qu’un oubli imposé soit possible.']]
],[['Mémoire','Représentation du passé portée par un individu ou un groupe, sélective et évolutive.'],['Histoire','Démarche critique de connaissance du passé fondée sur l’analyse des sources.'],['Devoir de mémoire','Expression désignant l’exigence morale de transmettre le souvenir d’événements, notamment de crimes ; elle ne remplace pas le travail historique.'],['Commémoration','Cérémonie ou pratique publique qui rappelle un événement passé.'],['Justice transitionnelle','Ensemble de mécanismes visant à traiter les violations massives des droits dans une société sortant d’un conflit ou d’une dictature.']],
[['Shoah','L’extermination des Juifs d’Europe par l’Allemagne nazie et ses collaborateurs ; mémoire, témoignages, archives et justice ont évolué depuis 1945.'],['Guerre d’Algérie','Les mémoires françaises et algériennes sont diverses et marquées par des expériences et récits parfois concurrents.'],['Procès de Nuremberg','1945-1946 : jugement de hauts responsables nazis et affirmation de responsabilités pénales individuelles pour des crimes internationaux.'],['Afrique du Sud','La Commission vérité et réconciliation (à partir de 1995) a privilégié la révélation publique des faits dans le contexte de la sortie de l’apartheid.']],
[['Distinguer histoire et mémoire','La mémoire transmet une expérience et une identité ; l’histoire vérifie et contextualise les traces du passé.'],['Comprendre les conflits mémoriels','Des groupes peuvent attribuer des sens différents au même événement.'],['Expliquer les politiques mémorielles','Les pouvoirs publics organisent reconnaissance, enseignement et commémorations, avec des débats possibles.'],['Associer histoire et justice','Les enquêtes historiques peuvent éclairer les faits ; les tribunaux établissent des responsabilités selon des règles juridiques.']],
[q('Quelle démarche caractérise le travail de l’historien ?',['La sélection des seuls souvenirs qui confortent une identité','La critique et la confrontation des sources','La répétition d’un récit officiel'],1,'L’histoire confronte les sources et construit une interprétation argumentée.'),q('Pourquoi les mémoires sont-elles plurielles ?',['Parce que tous les groupes vivent et interprètent le passé de la même manière','Parce que les expériences et les points de vue diffèrent','Parce que l’histoire interdit les témoignages'],1,'Les groupes n’ont pas les mêmes expériences, transmissions ni intérêts mémoriels.')]);

addCourse('hggsp','patrimoine','Thème 4 — Identifier, protéger et valoriser le patrimoine','Enjeux géopolitiques de la préservation',
'Le patrimoine rassemble des biens matériels et immatériels auxquels une société attribue une valeur historique, artistique, scientifique ou symbolique. Sa protection relève d’acteurs multiples et peut devenir un enjeu de puissance, de tourisme, d’identité et de relations internationales.',[
['1. La construction de la notion de patrimoine',['Le patrimoine n’est pas une catégorie immuable : les sociétés choisissent ce qu’elles souhaitent transmettre. Il peut être matériel (monuments, objets, paysages), immatériel (pratiques, langues, savoir-faire) ou naturel.','La patrimonialisation est le processus par lequel un élément est identifié, reconnu, protégé et transmis. Elle implique des choix : certains héritages sont mis en valeur, d’autres restent invisibles ou controversés.','L’UNESCO joue un rôle majeur avec la Convention du patrimoine mondial de 1972 et celle de 2003 sur le patrimoine culturel immatériel. L’inscription sur une liste favorise la reconnaissance, mais ne garantit pas à elle seule la conservation.']],
['2. Protéger et valoriser : coopérations et tensions',['La protection associe États, collectivités, communautés locales, chercheurs, associations et organisations internationales. Les financements, les normes de restauration et les usages touristiques font l’objet de négociations.','Le patrimoine peut être détruit volontairement lors d’un conflit pour atteindre l’identité d’un groupe. Il peut aussi être pillé, trafiqué ou fragilisé par l’urbanisation, le tourisme de masse et le changement climatique.','La valorisation peut soutenir l’économie locale et la transmission, mais elle comporte des risques de marchandisation et de mise à l’écart des habitants. Protéger suppose donc d’arbitrer entre conservation, accès du public et usages sociaux.']]
],[['Patrimoine','Héritage matériel, immatériel ou naturel reconnu comme ayant une valeur à transmettre.'],['Patrimonialisation','Processus de sélection, de reconnaissance et de protection d’un héritage.'],['Patrimoine mondial','Biens reconnus par l’UNESCO comme ayant une valeur universelle exceptionnelle selon la Convention de 1972.'],['Patrimoine immatériel','Pratiques, représentations, expressions, connaissances et savoir-faire transmis par des communautés.'],['Tourisme culturel','Déplacement motivé en partie par la découverte de patrimoines et de pratiques culturelles.']],
[['UNESCO','Organisation des Nations unies pour l’éducation, la science et la culture, créée en 1945.'],['Convention de 1972','Texte international concernant la protection du patrimoine mondial culturel et naturel.'],['Tombouctou','Des mausolées et manuscrits ont été menacés et détruits lors du conflit au Mali ; la reconstruction a mobilisé des acteurs nationaux et internationaux.'],['Venise','La fréquentation touristique et les risques environnementaux posent la question de l’équilibre entre conservation et vie locale.']],
[['Définir le patrimoine','Un héritage sélectionné et reconnu comme digne d’être transmis.'],['Expliquer la patrimonialisation','Un processus social et politique de reconnaissance, protection et valorisation.'],['Identifier les menaces','Conflits, trafics, dégradations, urbanisation, tourisme et changement climatique.'],['Montrer les tensions','La mise en valeur peut financer la protection mais aussi transformer les lieux et exclure des habitants.']],
[q('La patrimonialisation désigne…',['La destruction d’un monument','Le processus de reconnaissance et de protection d’un héritage','Uniquement la fréquentation touristique'],1,'La patrimonialisation transforme un héritage en patrimoine reconnu et protégé.'),q('La Convention de l’UNESCO de 1972 porte sur…',['Le patrimoine mondial culturel et naturel','Les règles du commerce maritime','La protection des réfugiés'],0,'La Convention de 1972 établit le cadre de protection du patrimoine mondial culturel et naturel.')]);

addCourse('hggsp','environnement','Thème 5 — L’environnement, entre exploitation et protection','Un enjeu planétaire',
'L’environnement est un objet de rivalités, de coopération et de politiques publiques. Les sociétés exploitent les ressources naturelles pour produire et se développer, mais cette exploitation transforme les milieux. La prise de conscience des limites écologiques a progressivement conduit à des mobilisations et à des négociations internationales.',[
['1. Exploiter, aménager et transformer les milieux',['Les sociétés dépendent des ressources naturelles : eau, sols, forêts, minerais, énergies et biodiversité. Les techniques et les besoins économiques transforment les paysages et les écosystèmes.','Les effets environnementaux sont inégalement répartis. Les populations les plus vulnérables sont souvent davantage exposées aux pollutions, aux risques et aux conséquences du changement climatique, alors qu’elles ont parfois moins contribué aux émissions.','La notion d’Anthropocène est utilisée par certains chercheurs pour désigner l’ampleur de l’impact humain sur le système Terre ; son statut de période géologique officielle est discuté.']],
['2. Protéger : mobilisations, gouvernance et limites',['La protection de l’environnement s’est construite à plusieurs échelles : parcs nationaux et réglementations locales, politiques nationales, conventions et conférences internationales.','Le sommet de la Terre de Rio (1992) contribue à institutionnaliser le développement durable et ouvre à la signature la Convention-cadre des Nations unies sur les changements climatiques et la Convention sur la diversité biologique.','L’Accord de Paris (2015) fixe l’objectif de maintenir l’élévation de la température moyenne bien en dessous de 2 °C et de poursuivre les efforts pour la limiter à 1,5 °C. Sa mise en œuvre dépend des contributions nationales, des financements et de la coopération.']],
['3. Des conflits d’usage et de justice environnementale',['Les politiques de protection peuvent entrer en tension avec les activités agricoles, industrielles, minières ou énergétiques. Les conflits d’usage opposent des acteurs qui attribuent des fonctions différentes à un même espace.','La justice environnementale interroge la répartition des nuisances, des ressources et des coûts de la transition. Les débats portent aussi sur la responsabilité historique des pays industrialisés et sur l’aide aux pays les plus vulnérables.','La transition écologique implique des transformations des modes de production, de transport, de consommation et des systèmes énergétiques. Elle pose la question de l’accompagnement social et de la répartition des efforts.']]
],[['Environnement','Ensemble des éléments naturels et humains qui entourent les sociétés et interagissent avec elles.'],['Développement durable','Mode de développement répondant aux besoins présents sans compromettre la capacité des générations futures à répondre aux leurs.'],['Anthropocène','Notion discutée décrivant l’importance des transformations humaines du système Terre.'],['Biodiversité','Diversité du vivant à l’échelle des écosystèmes, des espèces et des gènes.'],['Justice environnementale','Recherche d’une répartition équitable des risques, ressources et décisions environnementales.'],['Transition écologique','Transformation des systèmes de production et de consommation pour réduire les pressions sur les milieux.']],
[['Rio 1992','Sommet de la Terre qui renforce la gouvernance environnementale internationale.'],['COP21 et Accord de Paris','2015 : accord international sur le climat fondé sur des contributions nationales.'],['Protocole de Kyoto','1997 : objectifs contraignants de réduction des émissions pour des pays développés, selon le cadre de l’époque.'],['Amazonie','Espace de biodiversité et de ressources, soumis à la déforestation et à des conflits d’usage.']],
[['Comprendre la tension centrale','Les ressources sont nécessaires au développement, mais leur exploitation peut dégrader les milieux.'],['Changer d’échelle','Les enjeux environnementaux se jouent du local au mondial.'],['Identifier les acteurs','États, organisations internationales, entreprises, scientifiques, ONG et populations.'],['Évaluer les politiques','Les accords fixent des objectifs, mais leur efficacité dépend des moyens, du contrôle et de la volonté politique.']],
[q('L’Accord de Paris sur le climat date de…',['1992','2005','2015'],2,'L’Accord de Paris a été adopté lors de la COP21 en 2015.'),q('La justice environnementale étudie notamment…',['La répartition des risques et des ressources environnementales','Uniquement la protection des monuments','Les frontières maritimes'],0,'Elle s’intéresse aux inégalités d’exposition, d’accès aux ressources et de participation aux décisions.')]);

addCourse('hggsp','connaissance','Thème 6 — L’enjeu de la connaissance','Production, diffusion et partage des savoirs',
'La connaissance est une ressource stratégique. Elle se construit par la recherche, se diffuse grâce à l’éducation, aux médias et aux réseaux numériques, et peut être mobilisée au service de la puissance. Son accès est inégal et sa circulation pose des questions de liberté, de propriété et de contrôle.',[
['1. Produire et diffuser les connaissances',['La production de connaissances repose sur des institutions : universités, laboratoires, organismes publics, entreprises et réseaux de chercheurs. La recherche fondamentale vise à comprendre des phénomènes ; la recherche appliquée cherche à répondre à des besoins identifiés.','L’imprimerie, l’école de masse, les bibliothèques, les médias et Internet ont transformé les conditions de diffusion du savoir. Le numérique accélère la circulation des informations, mais facilite aussi la désinformation et la diffusion de contenus non vérifiés.','La science repose sur des méthodes de vérification, de discussion et de publication. Les résultats scientifiques sont discutables et révisables, mais cette révision ne signifie pas que toutes les opinions se valent.']],
['2. La connaissance, un facteur de puissance',['Les États investissent dans l’éducation, la recherche, les technologies et les infrastructures numériques pour renforcer leur compétitivité et leur autonomie. Les savoirs peuvent contribuer à la puissance militaire, économique, sanitaire et diplomatique.','La maîtrise des données, des semi-conducteurs, des réseaux et des technologies stratégiques est devenue un enjeu de souveraineté. Les dépendances technologiques peuvent fragiliser un État.','Les connaissances peuvent être protégées par le secret, les brevets et le droit d’auteur, ou partagées selon des principes d’ouverture. Les débats portent sur l’équilibre entre rémunération de l’innovation, circulation des savoirs et intérêt général.']],
['3. Inégalités et gouvernance du savoir',['L’accès à l’éducation, aux équipements numériques et aux publications scientifiques reste inégal entre territoires et groupes sociaux. La fracture numérique concerne les équipements, les compétences et la qualité des connexions.','La coopération scientifique internationale permet de mutualiser des équipements et des compétences, mais elle peut être affectée par les rivalités géopolitiques, les restrictions d’accès et les écarts de financement.','L’éducation aux médias et à l’information apprend à identifier une source, vérifier une affirmation, distinguer fait, interprétation et opinion, et comprendre les mécanismes de circulation des contenus.']]
],[['Connaissance','Ensemble organisé de savoirs construits, vérifiés et transmis.'],['Recherche fondamentale','Recherche visant d’abord à produire des connaissances et à comprendre des phénomènes.'],['Recherche appliquée','Recherche orientée vers la résolution d’un problème ou une application.'],['Souveraineté numérique','Capacité à maîtriser ses infrastructures, données et choix technologiques.'],['Fracture numérique','Inégalités d’accès aux outils numériques, aux connexions et aux compétences nécessaires.'],['Désinformation','Diffusion intentionnelle d’informations fausses ou trompeuses.']],
[['Imprimerie','La diffusion de l’imprimerie en Europe à partir du XVe siècle transforme la reproduction et la circulation des textes.'],['Internet','Réseau mondial qui accélère la circulation des informations et reconfigure les rapports de pouvoir.'],['Programme spatial','Les technologies spatiales associent recherche scientifique, infrastructures stratégiques et compétition entre puissances.'],['Semi-conducteurs','Composants essentiels aux équipements numériques ; leur production est concentrée et stratégique.']],
[['Connaissance et puissance','Les savoirs soutiennent l’innovation, l’autonomie et les capacités stratégiques.'],['Diffusion ambivalente','Le numérique facilite l’accès aux savoirs, mais aussi la désinformation.'],['Inégalités','L’accès aux savoirs dépend des infrastructures, des ressources et des compétences.'],['Gouvernance','La circulation des connaissances suppose des règles sur les données, la propriété intellectuelle et la coopération.']],
[q('Quelle distinction est correcte ?',['La recherche fondamentale vise d’abord à produire des connaissances','La recherche appliquée refuse toute application','La science repose uniquement sur l’opinion'],0,'La recherche fondamentale vise à comprendre ; la recherche appliquée cherche à répondre à des problèmes.'),q('La fracture numérique renvoie…',['Aux seules différences de vitesse des satellites','Aux inégalités d’accès, d’équipement et de compétences numériques','À une frontière politique'],1,'Elle comprend les inégalités matérielles et les inégalités de compétences.')]);

// SES — les 12 questions du programme de terminale
const sesData=[
['croissance','Quelles sont les sources et les défis de la croissance économique ?','Productivité, progrès technique et limites', 'La croissance économique est l’augmentation durable de la production de biens et services d’un territoire, mesurée par l’évolution du PIB en volume. Elle résulte de la mobilisation du travail et du capital, de l’amélioration de leur efficacité et du progrès technique.',[
['Mesurer et expliquer la croissance',['Le PIB mesure la valeur des biens et services finaux produits sur un territoire pendant une période. Pour comparer la production dans le temps, on raisonne en volume, en neutralisant l’effet de la hausse des prix. Le PIB par habitant donne une moyenne et ne renseigne pas directement sur la répartition des revenus ni sur le bien-être.','La croissance extensive provient de l’augmentation des quantités de facteurs de production (travail et capital). La croissance intensive vient de l’amélioration de leur efficacité, mesurée notamment par la productivité globale des facteurs (PGF).','Le capital humain correspond aux connaissances, compétences et états de santé qui améliorent les capacités productives. Le capital physique regroupe les biens de production durables. Le capital technologique incorpore des connaissances et innovations.']],
['Progrès technique et croissance endogène',['Le progrès technique désigne l’ensemble des innovations qui améliorent les produits, les procédés ou l’organisation. Il peut accroître la productivité, créer de nouveaux marchés et transformer les emplois.','Les théories de la croissance endogène soulignent le rôle des investissements en capital humain, recherche-développement, infrastructures et connaissances. Ces investissements peuvent produire des externalités positives : leurs bénéfices dépassent parfois ceux qui les financent.','La destruction créatrice, notion associée à Schumpeter, désigne le processus par lequel les innovations rendent certaines activités obsolètes tout en créant de nouveaux produits, entreprises et emplois.']],
['Limites et soutenabilité',['La croissance peut s’accompagner de pollution, d’épuisement de ressources et d’émissions de gaz à effet de serre. Le PIB ne mesure pas directement les dégradations environnementales ni la qualité de vie.','La soutenabilité interroge la possibilité de maintenir le bien-être dans le temps. Les analyses distinguent souvent soutenabilité faible (substitution possible entre formes de capital) et forte (préservation de certains capitaux naturels critiques).','Les politiques publiques peuvent encourager l’innovation propre, réglementer les émissions, taxer les externalités négatives et soutenir la recherche. Les arbitrages portent sur l’efficacité, la justice sociale et le rythme de la transition.']]],
[['PIB','Valeur des biens et services finaux produits sur un territoire durant une période.'],['Croissance économique','Hausse durable de la production de biens et services, mesurée par le PIB en volume.'],['Productivité','Rapport entre une production et les facteurs mobilisés pour l’obtenir.'],['PGF','Part de la croissance qui ne s’explique pas par la seule augmentation du travail et du capital mesurés.'],['Capital humain','Connaissances, compétences et capacités des individus.'],['Externalité','Effet de l’activité d’un agent sur le bien-être d’autres agents sans compensation par un prix.'],['Destruction créatrice','Processus d’innovation qui renouvelle les activités en en faisant disparaître certaines et en en créant d’autres.']],
[['Révolution industrielle','Les transformations techniques et organisationnelles ont contribué à des gains de productivité de long terme.'],['R&D','La recherche-développement peut créer des innovations et des externalités de connaissance.'],['PIB et bien-être','Une hausse du PIB ne garantit pas à elle seule une amélioration équitable du bien-être.']],
[['Mesure','Le PIB en volume mesure l’évolution de la production en corrigeant l’inflation.'],['Sources','Travail, capital, productivité, progrès technique et institutions.'],['Mécanismes','L’investissement, la formation et la R&D peuvent soutenir la productivité.'],['Limites','Inégalités, externalités environnementales et soutenabilité.']],
[q('Le PIB en volume permet surtout de…',['Mesurer la production en neutralisant l’effet des prix','Mesurer directement le bonheur','Mesurer uniquement les exportations'],0,'Le PIB en volume corrige l’effet de la variation des prix.'),q('La croissance intensive repose principalement sur…',['L’augmentation du nombre d’heures travaillées seulement','L’amélioration de l’efficacité des facteurs','La baisse de la population'],1,'Elle vient des gains de productivité et de l’efficacité accrue des facteurs.')]],
['commerce','Quels sont les fondements du commerce international et de l’internationalisation de la production ?','Spécialisation, échanges et chaînes de valeur','Le commerce international correspond aux échanges de biens et services entre pays. Il repose sur des différences de coûts et de productivité, mais aussi sur la différenciation des produits, les économies d’échelle et l’organisation internationale des firmes.',[
['Pourquoi les pays échangent-ils ?',['L’avantage comparatif (Ricardo) montre qu’un pays peut gagner à se spécialiser dans la production pour laquelle son coût d’opportunité est relativement le plus faible, même s’il n’a pas d’avantage absolu.','Les dotations en facteurs de production, les technologies, les qualifications, les ressources et les institutions contribuent aux spécialisations. Les échanges permettent d’accéder à une plus grande variété de produits et peuvent réduire certains coûts.','Le commerce entre pays comparables s’explique aussi par la différenciation horizontale (variétés différentes) et verticale (gammes de qualité/prix) et par les économies d’échelle.']],
['Firmes multinationales et chaînes de valeur',['Une firme multinationale possède ou contrôle des unités de production dans plusieurs pays. Elle peut fragmenter les étapes de conception, fabrication, assemblage et commercialisation selon les coûts, les compétences, les marchés et les risques.','Une chaîne de valeur mondiale répartit les étapes de production entre plusieurs territoires. Les échanges de biens intermédiaires prennent alors une place importante.','L’internationalisation peut prendre la forme d’investissements directs à l’étranger (IDE), de sous-traitance ou d’accords de partenariat. Les choix des firmes influencent les emplois, les transferts de technologie et la dépendance des territoires.']],
['Effets du commerce et débats sur le protectionnisme',['Le commerce peut accroître le pouvoir d’achat, la variété disponible, la concurrence et la productivité. Il peut aussi provoquer des pertes d’emplois ou des baisses de revenus dans certains secteurs exposés à la concurrence.','Les effets sont inégalement répartis entre consommateurs, travailleurs, entreprises et territoires. Les politiques d’accompagnement (formation, mobilité, protection sociale) jouent un rôle important.','Le protectionnisme utilise des droits de douane, quotas, normes ou subventions pour protéger certaines activités. Il peut soutenir des secteurs stratégiques, mais renchérit les importations et peut provoquer des représailles.']]],
[['Avantage comparatif','Capacité à produire un bien avec un coût d’opportunité relativement plus faible.'],['Dotation factorielle','Quantités relatives de travail, capital et ressources dont dispose un pays.'],['Économies d’échelle','Baisse du coût moyen de production lorsque les quantités produites augmentent.'],['FMN','Entreprise qui possède ou contrôle des unités de production dans plusieurs pays.'],['IDE','Investissement permettant d’acquérir un intérêt durable et une influence dans une entreprise située à l’étranger.'],['Chaîne de valeur mondiale','Répartition internationale des différentes étapes de conception et de production.'],['Protectionnisme','Mesures qui limitent ou renchérissent les importations pour protéger des producteurs.']],
[['Ricardo','Principes de l’économie politique et de l’impôt (1817) : théorie des avantages comparatifs.'],['Électronique','Un produit peut être conçu, fabriquer ses composants, assemblé et commercialisé dans plusieurs pays.'],['OMC','Organisation mondiale du commerce, créée en 1995, encadre les règles des échanges multilatéraux.']],
[['Fondements','Avantages comparatifs, dotations factorielles, technologie, différenciation et économies d’échelle.'],['Organisation','Les FMN répartissent les étapes de production dans des chaînes de valeur mondiales.'],['Gains et pertes','Le commerce peut accroître l’efficacité et le choix, mais ses effets distributifs sont inégaux.'],['Débat','Le protectionnisme peut protéger des secteurs mais a des coûts et risques de représailles.']],
[q('L’avantage comparatif repose sur…',['Le coût d’opportunité relatif','Le seul volume de population','La distance géographique uniquement'],0,'La spécialisation dépend du coût d’opportunité relatif.'),q('Un IDE correspond à…',['Un simple achat ponctuel de produit','Un investissement durable donnant une influence dans une entreprise étrangère','Une taxe à l’importation'],1,'L’IDE implique une relation durable et une influence dans une entreprise située à l’étranger.')]],
['emploi','Comment lutter contre le chômage ?','Marché du travail et politiques de l’emploi','Le chômage désigne la situation d’une personne sans emploi, disponible pour travailler et recherchant activement un emploi (définition du BIT). Son analyse distingue les causes conjoncturelles, structurelles et institutionnelles.',[
['Mesurer et analyser le chômage',['Au sens du BIT, un chômeur est sans emploi pendant la période de référence, disponible pour travailler et en recherche active. Le taux de chômage rapporte le nombre de chômeurs à la population active. Il ne doit pas être confondu avec le taux d’emploi.','Le chômage conjoncturel est lié à une insuffisance temporaire de la demande globale lors d’un ralentissement. Le chômage structurel résulte de désajustements durables : qualifications, localisation, institutions ou transformations productives.','Le halo du chômage regroupe des personnes proches du marché du travail qui souhaitent travailler mais ne remplissent pas tous les critères statistiques du chômage BIT. Le sous-emploi concerne notamment des personnes travaillant à temps partiel et souhaitant travailler davantage.']],
['Les mécanismes du marché du travail',['Dans l’analyse néoclassique, le salaire réel influence l’offre et la demande de travail ; des rigidités salariales peuvent contribuer au chômage. Cette approche insiste sur les coûts du travail et les incitations.','L’analyse keynésienne souligne qu’une demande globale insuffisante peut réduire la production et l’emploi : les entreprises n’embauchent pas si elles anticipent des débouchés faibles, même si les salaires diminuent.','Les inadéquations de compétences et les difficultés d’appariement entre offres et demandes d’emploi peuvent entretenir un chômage structurel. La formation et l’accompagnement améliorent l’appariement.']],
['Les politiques de lutte contre le chômage',['Les politiques de soutien à la demande (dépenses publiques, transferts, baisse d’impôts) cherchent à relancer l’activité et l’emploi lorsque le chômage est conjoncturel.','Les politiques d’offre réduisent certains coûts, encouragent l’investissement et l’embauche ou améliorent la compétitivité. Leur efficacité dépend du contexte et peut comporter des effets distributifs.','Les politiques actives comprennent formation, accompagnement, aides à l’embauche et amélioration de l’appariement. Les politiques passives indemnisent les chômeurs et soutiennent leurs revenus.']]],
[['Chômage BIT','Personne sans emploi, disponible et en recherche active selon les critères du Bureau international du travail.'],['Taux de chômage','Nombre de chômeurs rapporté à la population active.'],['Chômage conjoncturel','Chômage lié à une insuffisance de l’activité économique et de la demande.'],['Chômage structurel','Chômage lié à des désajustements durables du marché du travail.'],['Halo du chômage','Personnes souhaitant travailler mais ne répondant pas à tous les critères du chômage BIT.'],['Politiques actives','Mesures visant le retour à l’emploi et l’amélioration de l’appariement.'],['Politiques passives','Mesures d’indemnisation et de soutien du revenu des personnes sans emploi.']],
[['Crise de 2008-2009','Le recul de l’activité a entraîné une hausse du chômage dans de nombreux pays.'],['Formation professionnelle','Peut réduire les inadéquations de compétences lorsque les formations correspondent aux besoins.'],['BIT','Le Bureau international du travail harmonise la définition statistique du chômage.']],
[['Mesurer','Le taux de chômage concerne les chômeurs dans la population active.'],['Diagnostiquer','Conjoncturel, structurel, inadéquation, halo et sous-emploi.'],['Agir sur la demande','Relancer l’activité lorsque les débouchés sont insuffisants.'],['Agir sur l’offre et l’appariement','Formation, accompagnement, incitations et adaptation des compétences.']],
[q('Le taux de chômage rapporte les chômeurs…',['À la population totale','À la population active','Aux seuls salariés'],1,'La population active comprend les personnes en emploi et les chômeurs.'),q('Le chômage conjoncturel est notamment lié…',['À une insuffisance de la demande globale','Uniquement à un manque de diplômes','À la saison des récoltes seulement'],0,'Une baisse de la demande peut réduire la production et les embauches.')]],
['crises','Comment expliquer les crises financières et réguler le système financier ?','Instabilité, contagion et régulation','Le système financier met en relation les agents qui disposent d’une capacité de financement et ceux qui ont un besoin de financement. Il facilite l’investissement, mais l’interconnexion des marchés et la prise de risque peuvent produire des crises.',[
['Le financement et les marchés financiers',['Les agents peuvent se financer par crédit bancaire ou par émission de titres (actions et obligations). Les banques assurent notamment la transformation des échéances et la création monétaire par le crédit.','Une action représente une part du capital d’une entreprise ; une obligation est un titre de dette. Les marchés permettent de mobiliser l’épargne, de fixer des prix et de répartir les risques.','L’asymétrie d’information (sélection adverse et aléa moral) peut conduire à des décisions risquées ou à un rationnement du crédit.']],
['Les mécanismes des crises financières',['Une bulle financière apparaît lorsque le prix d’un actif s’éloigne durablement de sa valeur fondamentale sous l’effet d’anticipations autoréalisatrices et de comportements mimétiques.','Le retournement des anticipations provoque des ventes, une chute des prix et des pertes. L’endettement et l’interconnexion peuvent amplifier le choc et provoquer une contagion.','Une crise bancaire peut réduire le crédit à l’économie réelle, entraîner faillites, baisse de l’investissement et récession. La crise des subprimes de 2007-2008 illustre la propagation d’un choc immobilier et financier.']],
['Réguler pour limiter le risque systémique',['La régulation prudentielle impose des exigences de fonds propres, de liquidité et de gestion des risques aux établissements financiers. Les accords de Bâle renforcent progressivement ces exigences.','Les banques centrales peuvent fournir des liquidités et agir sur les taux d’intérêt. Les autorités de supervision surveillent les établissements et les risques systémiques.','La régulation vise à réduire la probabilité et le coût des crises, sans supprimer tout risque. Elle doit tenir compte de l’innovation financière, de l’arbitrage réglementaire et des interconnexions internationales.']]],
[['Action','Part du capital d’une entreprise.'],['Obligation','Titre de dette émis par une entreprise ou un État.'],['Bulle spéculative','Hausse autoentretenue du prix d’un actif, pouvant s’éloigner de ses fondamentaux.'],['Risque systémique','Risque qu’une défaillance se propage à l’ensemble du système financier.'],['Aléa moral','Situation où un acteur prend davantage de risques parce qu’il ne supporte pas entièrement les conséquences.'],['Régulation prudentielle','Règles visant à assurer la solidité des établissements financiers.']],
[['Subprimes','Crédits immobiliers risqués aux États-Unis, au cœur de la crise financière de 2007-2008.'],['Bâle III','Cadre prudentiel international adopté après la crise financière pour renforcer la solidité bancaire.'],['Banque centrale','Institution qui conduit la politique monétaire et peut fournir des liquidités au système bancaire.']],
[['Rôle du système','Financer l’économie et répartir les risques.'],['Origines des crises','Bulles, endettement, asymétries d’information et prises de risque.'],['Propagation','Interconnexion, pertes, défiance et contraction du crédit.'],['Régulation','Exigences prudentielles, supervision et intervention des banques centrales.']],
[q('Une action est…',['Un titre de propriété d’une fraction du capital','Un titre de dette','Un impôt'],0,'L’action donne un droit de propriété sur une partie du capital.'),q('Le risque systémique désigne…',['Le risque d’une seule entreprise sans effet externe','Le risque de propagation d’une défaillance à tout le système','Le risque d’inflation uniquement'],1,'Les interconnexions peuvent transmettre une défaillance au reste du système financier.')]],
['action','Quelles politiques économiques dans le cadre européen ?','Politiques conjoncturelles et intégration européenne','Les politiques économiques regroupent les interventions publiques destinées à influencer l’activité, l’emploi, les prix et la croissance. Dans la zone euro, la politique monétaire est commune, tandis que les politiques budgétaires restent principalement nationales mais coordonnées et encadrées.',[
['Politique budgétaire et politique monétaire',['La politique budgétaire agit sur les dépenses et recettes publiques. Elle peut soutenir la demande en période de ralentissement ou contribuer à réduire les déficits et la dette.','La politique monétaire agit sur les conditions de financement et la quantité de monnaie, notamment par les taux directeurs et les opérations de refinancement. Dans la zone euro, elle est conduite par la Banque centrale européenne (BCE).','Une politique conjoncturelle cherche à agir à court terme sur l’activité ; une politique structurelle transforme durablement le fonctionnement de l’économie (formation, concurrence, innovation, marché du travail).']],
['L’intégration économique européenne',['Le marché unique repose sur la libre circulation des biens, services, capitaux et personnes. Il favorise les échanges et la concurrence, mais nécessite des règles communes.','La zone euro partage une monnaie et une politique monétaire. Les États membres ne peuvent plus ajuster individuellement leur taux de change ou leur taux directeur.','Les politiques budgétaires nationales sont encadrées par des règles européennes visant la soutenabilité des finances publiques et coordonnées dans le cadre du semestre européen.']],
['Coordination et limites',['Les politiques économiques peuvent produire des effets de débordement entre pays : une relance dans un État peut soutenir les importations de ses partenaires ; une crise peut se propager.','La politique monétaire unique doit répondre à une situation moyenne de la zone euro, alors que les économies nationales connaissent des conjonctures différentes.','Les débats portent sur le dosage entre discipline budgétaire, stabilisation conjoncturelle, investissements communs et solidarité entre États.']]],
[['Politique budgétaire','Action sur les dépenses et recettes publiques pour influencer l’activité et les objectifs collectifs.'],['Politique monétaire','Action de la banque centrale sur les conditions monétaires et financières.'],['BCE','Banque centrale européenne, responsable de la politique monétaire de la zone euro.'],['Zone euro','Ensemble des États membres de l’Union européenne ayant adopté l’euro.'],['Marché unique','Espace de libre circulation des biens, services, capitaux et personnes.'],['Politique conjoncturelle','Politique visant à agir sur l’activité économique à court terme.'],['Politique structurelle','Politique visant à modifier durablement les structures de l’économie.']],
[['BCE','Créée en 1998 ; conduit la politique monétaire de la zone euro depuis le lancement de l’euro.'],['Euro','Monnaie scripturale introduite en 1999 et billets/pièces mis en circulation en 2002.'],['Semestre européen','Cycle annuel de coordination des politiques économiques et budgétaires.']],
[['Deux leviers','Budgétaire (gouvernements) et monétaire (banque centrale).'],['Zone euro','Politique monétaire commune, budgets nationaux encadrés et coordonnés.'],['Coordination','Les décisions d’un pays ont des effets sur ses partenaires.'],['Arbitrages','Stabilisation, soutenabilité de la dette, investissements et solidarité.']],
[q('Dans la zone euro, la politique monétaire est conduite par…',['La Commission européenne seule','La Banque centrale européenne','Chaque parlement national séparément'],1,'La BCE conduit la politique monétaire unique de la zone euro.'),q('La politique budgétaire agit principalement sur…',['Les dépenses et recettes publiques','Les taux directeurs de la BCE','Les frontières nationales'],0,'Elle utilise les dépenses et les prélèvements publics.')]],
['structure','Comment est structurée la société française actuelle ?','Groupes sociaux, hiérarchies et facteurs de différenciation','La structure sociale désigne la manière dont une société est organisée en groupes différenciés et hiérarchisés. Pour la décrire, on mobilise plusieurs critères : profession, revenu, diplôme, âge, genre, configuration familiale, lieu de résidence et origine sociale.',[
['Décrire la structure sociale',['Les professions et catégories socioprofessionnelles (PCS) regroupent les individus selon leur profession, leur statut, leur qualification et leur position dans l’organisation du travail. Elles permettent de comparer des groupes, mais ne résument pas toutes les dimensions des inégalités.','Les revenus, le patrimoine et le niveau de diplôme structurent les conditions de vie. Le patrimoine est généralement plus concentré que les revenus et contribue à la reproduction des positions sociales.','Le genre, l’âge, la composition du ménage, le territoire et l’origine sociale influencent les ressources et les trajectoires. Ces critères se combinent : on parle parfois d’intersection des rapports sociaux.']],
['Classes sociales : débats et transformations',['Marx analyse les classes à partir de la place dans les rapports de production et de l’opposition entre bourgeoisie et prolétariat. La classe en soi partage une position objective ; la classe pour soi développe une conscience et une organisation communes.','Weber propose une analyse multidimensionnelle : classes (situation économique), groupes de statut (prestige) et partis (pouvoir). Les hiérarchies ne se réduisent donc pas à la propriété des moyens de production.','La tertiarisation, la salarisation, la féminisation de l’emploi et l’élévation des qualifications transforment la structure sociale. Les frontières de classe peuvent être moins visibles sans que les inégalités disparaissent.']],
['Inégalités et distances sociales',['Les inégalités sont des différences d’accès à des ressources socialement valorisées qui produisent des avantages ou désavantages. Elles peuvent être économiques, culturelles, scolaires, politiques ou territoriales.','Les styles de vie, pratiques culturelles et réseaux de sociabilité peuvent maintenir des distances sociales. Les analyses doivent toutefois éviter de présenter les groupes comme homogènes.']]],
[['PCS','Catégories statistiques regroupant les professions selon plusieurs caractéristiques sociales et professionnelles.'],['Structure sociale','Organisation d’une société en groupes différenciés et hiérarchisés.'],['Classe sociale','Groupe défini selon une position dans la structure sociale ; sens variable selon les théories.'],['Inégalités sociales','Différences d’accès à des ressources valorisées qui se traduisent par des avantages ou désavantages.'],['Tertiarisation','Augmentation de la part des activités de services dans l’emploi et la production.']],
[['Marx','Analyse des classes à partir des rapports de production et des conflits d’intérêts.'],['Weber','Analyse multidimensionnelle des hiérarchies économiques, sociales et politiques.'],['PCS','Outil statistique de l’Insee pour décrire la population active et les ménages.']],
[['Décrire','Croiser profession, revenu, patrimoine, diplôme, genre, âge et territoire.'],['Expliquer','Les ressources et positions se cumulent et se transmettent parfois.'],['Débattre','Les classes sociales restent-elles pertinentes pour analyser les sociétés contemporaines ?'],['Nuancer','Les groupes sont hétérogènes et les critères de hiérarchie se combinent.']],
[q('Les PCS servent à…',['Classer les professions selon des caractéristiques sociales et professionnelles','Mesurer uniquement le patrimoine','Définir les frontières politiques'],0,'Les PCS sont un outil statistique de description de la structure sociale.'),q('Pour Weber, la stratification sociale est…',['Uniquement fondée sur la propriété','Multidimensionnelle','Sans rapport avec le prestige'],1,'Weber distingue notamment classes, groupes de statut et partis.')]],
['ecole','Quelle est l’action de l’École sur les destins individuels et sur l’évolution de la société ?','Massification, démocratisation et inégalités scolaires','L’École transmet des savoirs, délivre des diplômes et contribue à la socialisation. Elle favorise la mobilité et l’intégration, mais les parcours scolaires restent liés aux ressources familiales et aux mécanismes de sélection.',[
['Massification et démocratisation',['La massification scolaire désigne l’augmentation de la scolarisation et du nombre de diplômés. La démocratisation suppose une réduction des inégalités d’accès et de réussite entre groupes sociaux.','L’égalité formelle de traitement ne garantit pas l’égalité réelle des chances : les élèves ne disposent pas tous des mêmes ressources économiques, culturelles et linguistiques.','Les diplômes influencent l’accès à l’emploi, les revenus et la position sociale. L’allongement des études a donc des effets importants sur les trajectoires individuelles.']],
['Les mécanismes des inégalités scolaires',['Les familles transmettent des ressources matérielles, culturelles et relationnelles. La maîtrise des codes scolaires, les pratiques langagières et les attentes familiales peuvent faciliter la réussite.','Les choix d’orientation, les stratégies scolaires et les effets d’établissement contribuent à différencier les parcours. Les inégalités peuvent se cumuler au fil de la scolarité.','Bourdieu et Passeron analysent la manière dont l’École peut valoriser des dispositions culturelles inégalement distribuées et contribuer à la reproduction sociale. Cette approche n’implique pas que les trajectoires soient totalement déterminées.']],
['Réduire les inégalités',['Les politiques peuvent agir sur l’accès aux ressources, l’accompagnement, la mixité sociale, l’orientation et les conditions d’apprentissage.','Les dispositifs de compensation cherchent à tenir compte des inégalités de départ. Leur efficacité dépend des moyens, de la continuité et de l’adaptation aux besoins.']]],
[['Massification','Augmentation du nombre d’élèves scolarisés et du niveau moyen de diplôme.'],['Démocratisation scolaire','Réduction des inégalités sociales d’accès, de parcours et de réussite scolaires.'],['Capital culturel','Ressources culturelles incorporées, objectivées ou institutionnalisées.'],['Reproduction sociale','Transmission intergénérationnelle des positions et avantages sociaux.'],['Égalité des chances','Principe selon lequel l’origine sociale ne devrait pas déterminer les trajectoires.']],
[['Bourdieu et Passeron','La Reproduction (1970) analyse le rôle de l’institution scolaire dans la reproduction des hiérarchies sociales.'],['Diplômes','Ils certifient des compétences et jouent un rôle central dans l’accès aux emplois.'],['Politiques d’éducation prioritaire','Elles visent à réduire les inégalités liées aux contextes sociaux et territoriaux.']],
[['Rôle de l’École','Instruire, socialiser, certifier et contribuer à la mobilité sociale.'],['Massification ≠ démocratisation','Plus d’élèves scolarisés ne signifie pas automatiquement moins d’inégalités.'],['Origine sociale','Les ressources familiales influencent les parcours et les choix.'],['Action publique','Agir sur les ressources, l’orientation, la mixité et l’accompagnement.']],
[q('La massification scolaire désigne…',['La hausse du nombre d’élèves scolarisés','La disparition de toutes les inégalités','La sélection par le patrimoine'],0,'La massification concerne l’augmentation quantitative de la scolarisation.'),q('Le capital culturel est notamment associé à…',['Bourdieu','Keynes','Ricardo'],0,'Bourdieu analyse la transmission et les effets du capital culturel.')]],
['mobilite','Quelles sont les caractéristiques contemporaines et les facteurs de la mobilité sociale ?','Trajectoires, fluidité et reproduction sociale','La mobilité sociale désigne le changement de position sociale d’un individu ou d’un groupe. Elle peut être intergénérationnelle (comparaison avec les parents) ou intragénérationnelle (au cours de la vie). Les tables de mobilité permettent d’en mesurer certaines dimensions.',[
['Mesurer la mobilité sociale',['La mobilité intergénérationnelle compare la position sociale des individus à celle de leurs parents. La mobilité intragénérationnelle étudie les changements de position au cours d’une carrière.','La mobilité observée comprend la mobilité structurelle, liée aux transformations de la structure des emplois, et la mobilité nette ou fluidité sociale, qui cherche à isoler les chances relatives de mobilité.','Les tables de destinée indiquent ce que deviennent les enfants d’une origine sociale donnée ; les tables de recrutement indiquent l’origine sociale des membres d’une catégorie.']],
['Les facteurs de mobilité et de reproduction',['Les transformations de la structure des emplois (tertiarisation, hausse des qualifications, recul de certains métiers) créent une mobilité structurelle.','L’École et les diplômes jouent un rôle dans l’accès aux positions sociales, mais les ressources familiales et les inégalités de parcours influencent les chances de réussite.','Le patrimoine, les réseaux, le genre, les configurations familiales et les trajectoires professionnelles participent aussi à la mobilité ou à la reproduction.']],
['Fluidité sociale et limites des mesures',['La fluidité sociale compare les chances relatives d’accéder à différentes positions selon l’origine sociale. Une société peut connaître davantage de mobilité observée sans devenir plus fluide si la structure des emplois change.','Les catégories socioprofessionnelles ne captent pas toutes les dimensions du statut social. Les tables reposent sur des conventions de classement et décrivent des tendances, non des destins individuels.']]],
[['Mobilité sociale','Changement de position sociale d’un individu ou d’un groupe.'],['Mobilité intergénérationnelle','Comparaison de la position sociale des enfants avec celle de leurs parents.'],['Mobilité intragénérationnelle','Changement de position sociale au cours de la vie d’un individu.'],['Mobilité structurelle','Mobilité liée aux transformations de la structure des emplois.'],['Fluidité sociale','Égalité plus ou moins grande des chances relatives selon l’origine sociale.'],['Reproduction sociale','Maintien des positions sociales d’une génération à l’autre.']],
[['Tables de mobilité','Outils statistiques comparant origine sociale et position atteinte.'],['Tertiarisation','Transformation de la structure des emplois qui peut accroître la mobilité structurelle.'],['Diplômes','Ressource importante de mobilité, mais leur rendement dépend du contexte et de l’origine sociale.']],
[['Distinguer','Mobilité intergénérationnelle / intragénérationnelle ; observée / structurelle / fluidité.'],['Mesurer','Tables de destinée et de recrutement.'],['Expliquer','Structure des emplois, école, famille, patrimoine, genre et réseaux.'],['Nuancer','Mobilité observée accrue ne signifie pas nécessairement égalité des chances accrue.']],
[q('La mobilité structurelle est liée…',['Aux transformations de la structure des emplois','Uniquement aux choix personnels','À la variation des prix'],0,'Elle résulte notamment de la transformation de la répartition des professions.'),q('Une table de destinée indique…',['Ce que deviennent les individus issus d’une origine sociale donnée','Le prix des diplômes','Les revenus de chaque entreprise'],0,'Elle suit le devenir social des personnes selon leur origine.')]],
['travail','Quelles mutations du travail et de l’emploi ?','Organisation du travail, qualité de l’emploi et transformations','Le travail est une activité productive rémunérée ou non, tandis que l’emploi désigne une activité professionnelle rémunérée et déclarée dans un cadre institutionnel. Les formes d’organisation et les statuts d’emploi se transforment avec les techniques et les stratégies des entreprises.',[
['Travail, emploi et organisation productive',['Le travail est une activité humaine de production ; l’emploi correspond à une activité rémunérée inscrite dans un statut. Le chômage, l’inactivité et le sous-emploi sont des situations distinctes.','Le taylorisme repose sur la division horizontale et verticale du travail, la standardisation et le contrôle des temps. Le fordisme associe production de masse, standardisation et consommation de masse.','Les organisations post-tayloriennes valorisent davantage la polyvalence, l’autonomie, le travail en équipe et la qualité, mais peuvent aussi intensifier le travail et accroître les contraintes.']],
['Transformations des emplois et des statuts',['La salarisation correspond à l’augmentation de la part des salariés dans la population active. La tertiarisation correspond à la progression des services.','La précarisation renvoie à l’instabilité de l’emploi et à l’incertitude des conditions de travail et de revenus. Les contrats courts, le temps partiel subi et certaines formes de travail indépendant peuvent accroître cette insécurité.','Le numérique et les plateformes transforment le recrutement, le contrôle et la coordination du travail. Ils peuvent offrir de la flexibilité, mais posent des questions d’autonomie, de protection sociale et de subordination.']],
['Sens du travail et qualité de l’emploi',['Le travail peut procurer revenu, statut, sociabilité, identité et reconnaissance. Il peut aussi être source de pénibilité, de risques psychosociaux et de conflits.','La qualité de l’emploi se mesure à travers la rémunération, la stabilité, les conditions de travail, l’autonomie, les perspectives et la protection sociale.','Les mutations ne produisent pas les mêmes effets pour tous : elles dépendent du secteur, de la qualification, du genre et des ressources des travailleurs.']]],
[['Travail','Activité productive, rémunérée ou non, mobilisant des capacités humaines.'],['Emploi','Travail rémunéré exercé dans un cadre institutionnel et statistique.'],['Salarisation','Progression de la part des salariés dans la population active.'],['Tertiarisation','Progression des emplois et activités de services.'],['Précarisation','Développement de situations d’emploi instables ou de protections réduites.'],['Taylorisme','Organisation scientifique du travail fondée sur la division et la standardisation des tâches.'],['Qualité de l’emploi','Ensemble des dimensions de rémunération, stabilité, conditions, autonomie et protection.']],
[['Taylor','Principles of Scientific Management (1911) : organisation scientifique du travail.'],['Fordisme','Production de masse standardisée, associée à une consommation de masse.'],['Plateformes numériques','Elles mettent en relation clients et travailleurs et soulèvent des questions de statut et de contrôle.']],
[['Distinguer','Travail (activité) et emploi (activité rémunérée et reconnue statistiquement).'],['Organiser','Taylorisme, fordisme et organisations post-tayloriennes.'],['Transformer','Salarisation, tertiarisation, numérique et formes d’emploi.'],['Évaluer','La qualité du travail dépend de la stabilité, des conditions, du revenu et de l’autonomie.']],
[q('Le taylorisme repose notamment sur…',['La division et la standardisation des tâches','L’absence de contrôle','La suppression de toute hiérarchie'],0,'Le taylorisme organise scientifiquement le travail par division des tâches et contrôle.'),q('La tertiarisation désigne…',['La progression des services dans l’économie et l’emploi','La baisse de la population active','La hausse des droits de douane'],0,'La tertiarisation correspond à la montée du secteur tertiaire.')]],
['engagement','Comment expliquer l’engagement politique dans les sociétés démocratiques ?','Participation, répertoires d’action et déterminants','L’engagement politique désigne les actions par lesquelles des individus cherchent à influencer les décisions collectives ou l’organisation de la société. Il prend des formes conventionnelles et non conventionnelles, individuelles ou collectives.',[
['Les formes de la participation politique',['La participation conventionnelle comprend le vote, l’adhésion à un parti, le militantisme électoral et le contact avec les élus.','La participation non conventionnelle comprend manifestations, grèves, pétitions, boycott, désobéissance civile ou mobilisations numériques. Les répertoires d’action évoluent avec les contextes et les technologies.','L’engagement peut être individuel ou collectif, ponctuel ou durable, institutionnalisé ou autonome. Il ne se limite pas à la participation électorale.']],
['Les déterminants de l’engagement',['La socialisation politique transmet des valeurs, opinions et habitudes de participation au sein de la famille, de l’école, des groupes de pairs et des médias.','Le diplôme, l’âge, le genre, la position sociale, le sentiment de compétence politique et les ressources disponibles influencent les formes d’engagement.','L’engagement dépend aussi des opportunités politiques, de la confiance dans les institutions, de l’efficacité perçue de l’action et des réseaux militants.']],
['Action collective et renouvellement',['Olson souligne le problème du passager clandestin : un individu peut bénéficier d’un bien collectif sans contribuer à sa production. Les incitations sélectives et les organisations peuvent faciliter la mobilisation.','Les nouveaux mouvements sociaux mettent souvent en avant des enjeux identitaires, environnementaux, féministes ou liés aux droits. Ils ne remplacent pas nécessairement les mobilisations liées au travail et aux revenus.','Les réseaux numériques facilitent la circulation des informations et la coordination, mais ne garantissent pas à eux seuls une mobilisation durable.']]],
[['Engagement politique','Action visant à influencer les décisions collectives ou l’organisation de la société.'],['Participation conventionnelle','Vote, adhésion partisane, militantisme électoral et contact avec les élus.'],['Action collective','Mobilisation coordonnée de plusieurs individus autour d’un objectif commun.'],['Socialisation politique','Processus d’acquisition et de transformation des opinions et comportements politiques.'],['Passager clandestin','Individu qui bénéficie d’un bien collectif sans contribuer à sa production.'],['Répertoire d’action','Ensemble des moyens d’action disponibles et utilisés par un mouvement.']],
[['Olson','The Logic of Collective Action (1965) : problème du passager clandestin et incitations à agir.'],['Vote','Forme institutionnalisée de participation politique, dont la fréquence et les déterminants varient.'],['Mobilisations environnementales','Elles combinent manifestations, campagnes, actions juridiques et mobilisation numérique.']],
[['Formes','Vote, militantisme, manifestation, grève, pétition, boycott et actions numériques.'],['Déterminants','Socialisation, ressources, compétences, âge, diplôme, genre et confiance.'],['Action collective','Problème du passager clandestin et rôle des organisations.'],['Évolution','Diversification des causes et des répertoires, sans disparition des formes anciennes.']],
[q('Le problème du passager clandestin est associé à…',['Mancur Olson','David Ricardo','Émile Durkheim'],0,'Olson analyse la difficulté à produire un bien collectif lorsque chacun peut en bénéficier sans contribuer.'),q('Le vote est une forme de participation…',['Conventionnelle','Toujours illégale','Uniquement numérique'],0,'Le vote est une forme institutionnalisée de participation politique.')]],
['justice-sociale','Quelles inégalités sont compatibles avec les différentes conceptions de la justice sociale ?','Égalité, équité et protection sociale','La justice sociale porte sur la manière de répartir les ressources, les droits, les opportunités et les risques. Les conceptions de la justice ne donnent pas toutes la même place à l’égalité, au mérite, à la liberté et à la solidarité.',[
['Les conceptions de la justice',['L’égalité des droits garantit les mêmes droits fondamentaux ; l’égalité des chances cherche à rendre les positions accessibles indépendamment de l’origine ; l’égalité des situations vise à réduire les écarts de ressources ou de conditions de vie.','L’équité adapte le traitement à des situations différentes afin de rechercher une justice plus substantielle. Elle peut justifier des mesures différenciées, par exemple des politiques de compensation.','Les conceptions libérales mettent l’accent sur les libertés et les droits ; les conceptions égalitaristes accordent davantage d’importance à la réduction des inégalités de ressources et de pouvoir.']],
['Les instruments de la justice sociale',['La redistribution verticale réduit les écarts de revenus entre ménages ; la redistribution horizontale couvre les risques sociaux au cours de la vie (maladie, vieillesse, chômage, famille).','Les prélèvements obligatoires financent les prestations et services publics. Ils peuvent être progressifs, proportionnels ou forfaitaires selon leur mode de calcul.','Les services collectifs (éducation, santé, transports) contribuent à l’égalité d’accès et peuvent réduire les inégalités, même lorsqu’ils ne prennent pas la forme d’un transfert monétaire.']],
['Débats et limites',['La redistribution peut réduire la pauvreté et les inégalités, mais son financement et ses effets sur les incitations sont discutés. L’évaluation doit distinguer les effets sur les revenus, les opportunités et les conditions de vie.','Les inégalités ne sont pas toutes jugées injustes de la même manière : le débat porte sur leur origine, leur ampleur, leur utilité éventuelle et leur compatibilité avec les libertés.']]],
[['Égalité des droits','Même reconnaissance de droits fondamentaux pour tous.'],['Égalité des chances','Réduction de l’influence de l’origine sociale sur l’accès aux positions.'],['Égalité des situations','Réduction des écarts de ressources et de conditions de vie.'],['Équité','Traitement différencié visant une justice adaptée aux situations.'],['Redistribution verticale','Transferts qui réduisent les écarts de revenus entre groupes.'],['Redistribution horizontale','Transferts couvrant des risques sociaux entre étapes de la vie.'],['Prélèvements obligatoires','Impôts et cotisations sociales finançant les dépenses publiques et sociales.']],
[['Impôt progressif','Le taux moyen augmente avec le revenu imposable.'],['Protection sociale','Ensemble des dispositifs couvrant les risques sociaux.'],['Services publics','Éducation et santé contribuent à l’accès aux ressources et aux opportunités.']],
[['Définir la justice','Répartition des droits, ressources, opportunités et risques.'],['Distinguer les égalités','Droits, chances et situations.'],['Redistribuer','Verticalement pour réduire les écarts ; horizontalement pour couvrir les risques.'],['Discuter','Liberté, mérite, solidarité, efficacité et réduction des inégalités.']],
[q('La redistribution horizontale vise principalement à…',['Couvrir les risques sociaux au cours de la vie','Réduire uniquement les écarts entre riches et pauvres','Financer les exportations'],0,'Elle mutualise des risques comme la maladie, la vieillesse ou le chômage.'),q('L’égalité des chances cherche à…',['Rendre les positions accessibles indépendamment de l’origine sociale','Rendre tous les revenus identiques','Supprimer les droits individuels'],0,'Elle vise à limiter l’effet de l’origine sur les trajectoires.')]],
['environnement','Quelle action publique pour l’environnement ?','Défaillances de marché, instruments et gouvernance','Les dégradations environnementales résultent notamment d’externalités négatives et de biens communs surexploités. L’action publique peut modifier les incitations, fixer des normes, créer des marchés de droits ou soutenir les innovations.',[
['Pourquoi le marché ne protège-t-il pas spontanément l’environnement ?',['Une externalité négative apparaît lorsqu’une activité impose un coût à des tiers sans compensation : la pollution peut donc être excessive si son coût social n’est pas pris en compte.','Un bien commun est rival mais difficilement excluable : chacun peut avoir intérêt à l’exploiter, ce qui crée un risque de surexploitation. Un bien collectif pur est non rival et non excluable.','L’information imparfaite, les horizons de décision courts et les effets transfrontaliers compliquent la coordination des acteurs.']],
['Les instruments de l’action publique',['La réglementation fixe des normes, interdictions ou obligations. Elle est utile lorsque des seuils doivent être respectés, mais suppose contrôle et sanctions.','La taxation environnementale donne un prix à la pollution et incite à réduire les émissions. Son effet dépend du niveau du prix, des possibilités de substitution et de l’accompagnement des ménages modestes.','Les marchés de quotas fixent une quantité totale d’émissions autorisées et permettent l’échange de droits. Les subventions et investissements publics soutiennent les technologies moins polluantes.']],
['Échelles, coopération et justice',['Les pollutions et le climat dépassent les frontières nationales. Les accords internationaux cherchent à coordonner les efforts, mais souffrent de divergences d’intérêts, de capacités et de responsabilités historiques.','Les politiques environnementales ont des effets sociaux différenciés. Une taxe peut peser proportionnellement davantage sur les ménages modestes si elle n’est pas compensée.','La transition juste cherche à répartir les coûts et bénéfices de la transformation écologique et à accompagner les travailleurs et territoires concernés.']]],
[['Externalité négative','Coût imposé à autrui sans compensation par le marché.'],['Bien commun','Bien rival dont l’exclusion des utilisateurs est difficile.'],['Réglementation','Instrument public qui impose des règles et des normes.'],['Taxe pigouvienne','Taxe visant à internaliser le coût externe d’une activité.'],['Marché de quotas','Système fixant un plafond d’émissions et autorisant l’échange de droits.'],['Transition juste','Transformation écologique accompagnée pour répartir équitablement ses coûts et bénéfices.']],
[['Pigou','L’analyse des externalités justifie une intervention visant à rapprocher coût privé et coût social.'],['Protocole de Kyoto','1997 : accord international établissant des objectifs de réduction pour des pays industrialisés.'],['Accord de Paris','2015 : cadre mondial de lutte contre le changement climatique.']],
[['Défaillances','Externalités, biens communs, information imparfaite et coordination.'],['Instruments','Normes, taxes, quotas, subventions et investissements publics.'],['Échelle','Locale, nationale, européenne et internationale.'],['Justice','Compenser les effets distributifs et accompagner les territoires et travailleurs.']],
[q('Une externalité négative est…',['Un coût imposé à des tiers sans compensation','Un bénéfice privé sans prix','Une hausse du salaire'],0,'La pollution peut imposer un coût à la société qui n’est pas intégré au prix.'),q('Un marché de quotas repose sur…',['Un plafond d’émissions et l’échange de droits','Une interdiction de tout commerce','Une subvention automatique à tous les ménages'],0,'Le plafond fixe la quantité totale autorisée, les quotas peuvent être échangés.')]]
];
for(const d of sesData){const [id,title,subtitle,intro,sections,notions,examples,sheet,quiz]=d;addCourse('ses',id,title,subtitle,intro,sections,notions,examples,sheet,quiz);}
