// Philosophie — les 17 notions du programme. Chaque fiche articule définitions, distinctions, auteurs et exemples.
const philoData=[
['art','L’art','Création, beauté et imitation','L’art est une activité de création d’œuvres auxquelles une valeur esthétique, symbolique ou expressive est attribuée. Il ne se réduit ni à la beauté ni à la reproduction du réel.',[['Art et technique',['La technique vise généralement une efficacité déterminée ; l’art peut mobiliser des techniques mais ne se réduit pas à leur application. L’œuvre suppose une intention, une forme et une interprétation.','L’art peut imiter la nature, mais il peut aussi transformer le réel, exprimer une expérience ou inventer des formes inédites.']],['L’œuvre et le jugement esthétique',['Le beau n’est pas simplement l’agréable : le jugement esthétique prétend souvent dépasser la préférence privée, sans se démontrer comme un théorème.','Une œuvre peut déranger, choquer ou représenter le laid sans perdre sa dimension artistique. La valeur d’une œuvre ne se réduit pas à son prix ou à sa popularité.']]], [['Imitation','Représentation ou reprise de traits du réel.'],['Jugement esthétique','Appréciation portant sur la forme et la valeur sensible d’une œuvre.'],['Génie','Capacité créatrice qui produit des œuvres originales sans suivre simplement des règles préétablies.']], [['Platon','Dans La République, il critique l’imitation artistique lorsqu’elle éloigne de la vérité.'],['Aristote','La Poétique analyse la mimèsis et la fonction de la tragédie.'],['Kant','La Critique de la faculté de juger distingue le jugement de goût de l’intérêt pratique.']], [['L’art imite-t-il ou transforme-t-il le réel ?','Le jugement de goût est-il subjectif ?','Une œuvre doit-elle être belle pour être artistique ?']], [q('Le jugement esthétique porte principalement sur…',['La valeur sensible et formelle d’une œuvre','Son rendement financier uniquement','Sa conformité à une loi'],0,'Le jugement esthétique apprécie l’œuvre, sans se réduire à son prix ou à son utilité.')]],
['bonheur','Le bonheur','Désir, plaisir et satisfaction','Le bonheur désigne un état durable de satisfaction de l’existence, à distinguer du plaisir ponctuel et de la joie passagère. Il pose la question de ce qui rend une vie bonne.',[['Bonheur et désir',['Les désirs peuvent orienter l’action, mais leur satisfaction indéfinie peut entretenir le manque. Il faut distinguer désirs naturels et nécessaires, désirs naturels non nécessaires et désirs vains.','Épicure propose une hiérarchie des désirs et une recherche de l’ataraxie, absence de trouble de l’âme.']],['Bonheur et raison',['Pour les stoïciens, la sagesse consiste à distinguer ce qui dépend de nous et ce qui n’en dépend pas, afin de ne pas faire dépendre la tranquillité d’événements extérieurs.','Le bonheur peut-il être un objectif direct ? Mill associe le bonheur au principe d’utilité, tandis que Kant distingue bonheur et moralité : agir moralement ne garantit pas d’être heureux.']]], [['Plaisir','Satisfaction sensible ou affective, souvent ponctuelle.'],['Bonheur','Satisfaction durable et globale de l’existence.'],['Ataraxie','Absence de trouble de l’âme.'],['Eudémonisme','Doctrine qui fait du bonheur la fin de l’existence humaine.']], [['Épicure','Lettre à Ménécée : distinguer les désirs et rechercher une vie sans trouble.'],['Épictète','Manuel : distinguer ce qui dépend de nous et ce qui n’en dépend pas.'],['Kant','La moralité ne peut pas être fondée sur la recherche du bonheur.']], [['Le bonheur est-il la satisfaction de tous les désirs ?','Peut-on être heureux seul ?','Le bonheur dépend-il de nous ?']], [q('L’ataraxie désigne…',['L’absence de trouble de l’âme','La recherche de richesse','La domination politique'],0,'L’ataraxie est un état de tranquillité recherché par certaines philosophies antiques.')]],
['conscience','La conscience','Présence à soi et connaissance de soi','La conscience est la capacité d’éprouver des états, de se représenter le monde et de se rapporter à soi. Elle peut désigner la conscience immédiate, la conscience réflexive et la conscience morale.',[['Conscience et identité',['La conscience immédiate accompagne les perceptions et les pensées. La conscience réflexive permet de prendre ses propres états pour objet et de se reconnaître comme sujet.','Descartes fait du cogito (« je pense ») une certitude première : même le doute confirme l’existence du sujet pensant.']],['Limites de la conscience',['La conscience ne connaît pas nécessairement toutes les causes de ses pensées et de ses actes. Freud montre que des processus inconscients peuvent influencer la vie psychique.','La mémoire, le corps, le langage et le regard d’autrui participent à la construction de l’identité personnelle.']]], [['Conscience immédiate','Présence vécue à ses perceptions et pensées.'],['Conscience réflexive','Capacité de se prendre soi-même pour objet de pensée.'],['Cogito','Certitude de l’existence du sujet en tant qu’il pense.'],['Conscience morale','Capacité à juger ses actes au regard de normes et de valeurs.']], [['Descartes','Méditations métaphysiques : le doute conduit à la certitude du cogito.'],['Locke','L’identité personnelle est liée à la continuité de la conscience et de la mémoire.'],['Freud','L’inconscient met en question la transparence du sujet à lui-même.']], [['Suis-je transparent à moi-même ?','La conscience suffit-elle à définir l’identité personnelle ?','Peut-on être responsable de ce dont on n’a pas conscience ?']], [q('Le cogito cartésien établit…',['La certitude du sujet pensant','L’impossibilité de penser','La supériorité de la mémoire'],0,'Le doute ne peut pas supprimer le fait qu’un sujet pense au moment où il doute.')]],
['devoir','Le devoir','Obligation morale, loi et liberté','Le devoir désigne ce qu’une personne doit faire au regard d’une obligation. Il peut être juridique, social ou moral. La question est de savoir si l’action morale doit venir de la contrainte, de l’intérêt ou de la raison.',[['Obéir ou être autonome',['Une obligation juridique est imposée par une règle extérieure et assortie de sanctions. Le devoir moral prétend obliger la conscience indépendamment d’un avantage personnel.','Kant distingue agir conformément au devoir et agir par devoir : la valeur morale dépend du principe de l’action, non de son seul résultat.']],['Universalité et responsabilité',['L’impératif catégorique demande d’agir selon une maxime que l’on peut vouloir comme loi universelle. Il ne s’agit pas de suivre ses préférences mais de respecter la rationalité morale.','Le devoir peut entrer en conflit avec des obligations particulières ; le jugement pratique doit examiner les circonstances sans réduire la morale au calcul d’intérêt.']]], [['Obligation','Exigence qui s’impose à l’action.'],['Autonomie','Capacité de se donner à soi-même une loi rationnelle.'],['Hétéronomie','Détermination de la volonté par une règle ou un intérêt extérieur.'],['Impératif catégorique','Commandement moral inconditionnel chez Kant.']], [['Kant','Fondements de la métaphysique des mœurs : agir selon une maxime universalisable.'],['Antigone','La tragédie met en scène un conflit entre loi de la cité et devoir familial/religieux.']], [['Doit-on toujours obéir à la loi ?','Peut-on agir moralement par intérêt ?','Le devoir limite-t-il ou fonde-t-il la liberté ?']], [q('Pour Kant, agir par devoir signifie…',['Agir par respect pour la loi morale','Agir uniquement pour obtenir une récompense','Obéir à toute autorité sans réfléchir'],0,'La valeur morale tient au principe rationnel de l’action, et non à l’intérêt.')]],
['etat','L’État','Pouvoir, loi et souveraineté','L’État est une institution politique qui exerce une autorité souveraine sur une population et un territoire. Il établit des lois, organise la vie collective et revendique le monopole de la violence physique légitime.',[['Pourquoi un État ?',['L’État rend possible une organisation commune, la production de règles et la résolution institutionnelle des conflits. Il peut garantir les droits et la sécurité, mais aussi exercer une domination.','Hobbes justifie un pouvoir souverain fort pour sortir de l’insécurité de l’état de nature. Locke insiste sur la protection des droits naturels et le consentement.']],['Légitimité et limites du pouvoir',['La légalité désigne la conformité à la loi ; la légitimité renvoie à la justification du pouvoir. Un pouvoir légal peut être contesté comme injuste.','Montesquieu défend la séparation des pouvoirs pour empêcher leur concentration. Rousseau pense la souveraineté comme expression de la volonté générale.']],['État et liberté',['L’État peut protéger les libertés en garantissant les droits et en limitant les violences privées. Mais il peut aussi restreindre les libertés par la surveillance ou l’arbitraire. Le problème est celui des limites et du contrôle du pouvoir.']]], [['Souveraineté','Pouvoir suprême de décision sur un territoire et une population.'],['Légitimité','Caractère d’un pouvoir considéré comme justifié.'],['État de droit','État dans lequel les pouvoirs publics sont soumis au droit.'],['Monopole de la violence légitime','Formule de Max Weber pour caractériser une prérogative centrale de l’État moderne.']], [['Hobbes','Léviathan (1651) : le souverain garantit la sécurité.'],['Locke','Second traité du gouvernement civil : le pouvoir protège les droits naturels.'],['Montesquieu','De l’esprit des lois (1748) : séparation des pouvoirs.'],['Rousseau','Du contrat social (1762) : souveraineté populaire et volonté générale.']], [['L’État est-il nécessaire à la liberté ?','Qu’est-ce qui rend un pouvoir légitime ?','Peut-on désobéir à un État injuste ?']], [q('La séparation des pouvoirs est associée à…',['Montesquieu','Épicure','Freud'],0,'Montesquieu défend la séparation des pouvoirs pour limiter l’arbitraire.')]],
['inconscient','L’inconscient','Désirs, refoulement et déterminismes psychiques','L’inconscient désigne ce qui, dans la vie psychique, échappe à la conscience tout en pouvant influencer les pensées, les émotions et les conduites. La psychanalyse en fait une dimension centrale du psychisme.',[['L’inconscient psychique',['Freud distingue le conscient, le préconscient et l’inconscient dans sa première topique. Des désirs ou représentations refoulés peuvent continuer à agir sans être directement accessibles à la conscience.','Le rêve, le lapsus et certains symptômes sont interprétés par Freud comme des formations où s’expriment indirectement des conflits psychiques.']],['Conscience et responsabilité',['La découverte de l’inconscient remet en cause l’idée d’un sujet totalement transparent à lui-même. Elle ne signifie pas que toute responsabilité disparaît : comprendre les déterminations peut aider à agir autrement.','La notion d’inconscient dépasse la psychanalyse dans certains usages, mais il faut distinguer les modèles scientifiques et les interprétations théoriques.']]], [['Inconscient','Processus psychiques non conscients qui influencent la vie mentale.'],['Refoulement','Mécanisme par lequel une représentation conflictuelle est maintenue hors de la conscience.'],['Lapsus','Erreur de parole ou d’écriture pouvant, selon Freud, révéler un conflit ou un désir.'],['Psychanalyse','Méthode d’exploration du psychisme développée par Freud.']], [['Freud','L’Interprétation du rêve (1900) : analyse du rêve comme voie d’accès à l’inconscient.'],['Nietzsche','Critique de l’illusion d’un sujet entièrement maître de ses motivations.']], [['Suis-je maître de mes pensées ?','L’inconscient supprime-t-il la responsabilité ?','Peut-on se connaître sans se connaître entièrement ?']], [q('Le refoulement est…',['Un mécanisme de maintien hors de la conscience','Une décision juridique','Une preuve que le rêve est toujours vrai'],0,'Dans la théorie freudienne, le refoulement maintient certaines représentations hors de la conscience.')]],
['justice','La justice','Droit, égalité et équité','La justice peut désigner une institution qui applique le droit, une vertu morale ou un idéal de répartition équitable. Elle pose la question des critères selon lesquels les personnes doivent être traitées.',[['Justice et droit',['Le droit positif rassemble les règles en vigueur dans une société. Le droit naturel désigne des principes considérés comme supérieurs aux lois établies. Une loi peut être légale sans être moralement juste.','La justice distributive concerne la répartition des biens, des charges et des honneurs ; la justice corrective vise à réparer un tort ou rétablir un équilibre.']],['Égalité et équité',['Traiter chacun de manière identique peut produire des effets injustes lorsque les situations de départ sont différentes. L’équité adapte le traitement à des circonstances pertinentes.','Rawls propose de choisir les principes de justice derrière un voile d’ignorance, sans connaître sa place future dans la société. Il défend des libertés égales et une organisation des inégalités avantageant les plus défavorisés, sous conditions.']]], [['Justice distributive','Répartition des biens et des charges selon un principe jugé juste.'],['Justice corrective','Réparation d’un tort ou rétablissement d’un équilibre.'],['Équité','Adaptation du traitement aux différences pertinentes de situation.'],['Droit positif','Ensemble des règles juridiques effectivement en vigueur.']], [['Aristote','Éthique à Nicomaque : distinctions entre justice distributive et corrective.'],['Rawls','Théorie de la justice (1971) : voile d’ignorance et principes de justice.'],['Pascal','Les Pensées interrogent la relation entre force, justice et loi.']], [['Une loi peut-elle être injuste ?','Faut-il traiter tout le monde de la même manière ?','Les inégalités peuvent-elles être justes ?']], [q('Le voile d’ignorance est associé à…',['John Rawls','Thomas Hobbes','Karl Marx'],0,'Rawls propose de choisir des principes sans connaître sa position sociale future.')]],
['langage','Le langage','Signes, pensée et communication','Le langage est un système de signes permettant de communiquer, de penser et de construire des significations. Il est à la fois un outil social, une condition de la pensée et un moyen de pouvoir.',[['Langage et pensée',['Le langage permet de formuler, stabiliser et partager des pensées. Mais la pensée ne se réduit pas toujours aux mots : images, émotions et intuitions peuvent précéder leur formulation.','Les langues découpent et organisent l’expérience de façons diverses. Apprendre une langue, c’est aussi accéder à des catégories et à des pratiques culturelles.']],['Langage et communication',['Un signe associe une forme et un sens selon des conventions partagées. La communication suppose un contexte, un destinataire et des règles d’interprétation.','Le langage peut informer, persuader, ordonner, séduire ou manipuler. La rhétorique étudie les moyens de convaincre ; elle peut servir la vérité comme la tromperie.']]], [['Signe','Élément qui renvoie à une signification selon un code.'],['Langue','Système social de signes et de règles partagé par une communauté.'],['Parole','Usage individuel et concret d’une langue.'],['Rhétorique','Art et techniques du discours visant à convaincre ou persuader.']], [['Saussure','Cours de linguistique générale : distinction entre langue et parole.'],['Aristote','La Rhétorique analyse les moyens de persuasion.'],['Wittgenstein','Les usages du langage sont liés à des formes de vie et à des jeux de langage.']], [['La pensée dépend-elle du langage ?','Le langage sert-il seulement à communiquer ?','Les mots peuvent-ils manipuler la pensée ?']], [q('La distinction langue/parole est associée à…',['Saussure','Kant','Bergson'],0,'Saussure distingue le système collectif de la langue et ses usages individuels.')]],
['liberte','La liberté','Libre arbitre, déterminisme et autonomie','La liberté peut désigner l’absence de contrainte, la capacité de choisir ou l’autonomie rationnelle. Elle suppose de distinguer les obstacles extérieurs, les déterminations et la responsabilité.',[['Liberté et contrainte',['La liberté négative désigne l’absence d’entraves ; la liberté positive concerne la capacité effective d’agir et de réaliser ses choix.','Une contrainte extérieure limite l’action, mais toute règle n’est pas nécessairement contraire à la liberté : une loi commune peut protéger chacun contre l’arbitraire.']],['Libre arbitre et déterminisme',['Le libre arbitre désigne la capacité de choisir entre plusieurs possibilités. Le déterminisme affirme que les événements, y compris les actions humaines, ont des causes.','Spinoza critique l’illusion du libre arbitre : les humains se croient libres parce qu’ils connaissent leurs désirs mais ignorent les causes qui les déterminent.']],['Autonomie et responsabilité',['Pour Kant, être libre ne consiste pas à satisfaire tous ses désirs, mais à agir selon une loi que la raison se donne. L’autonomie s’oppose à l’hétéronomie.','La responsabilité suppose de pouvoir attribuer un acte à un sujet, en tenant compte de ses intentions, de ses capacités et des contraintes.']]], [['Liberté négative','Absence d’obstacles et d’ingérences.'],['Liberté positive','Capacité réelle de se gouverner et d’agir.'],['Déterminisme','Principe selon lequel les phénomènes sont liés à des causes.'],['Libre arbitre','Pouvoir de choisir entre plusieurs possibilités.'],['Autonomie','Capacité de se donner une loi rationnelle.']], [['Spinoza','Éthique : critique de l’illusion du libre arbitre.'],['Kant','La liberté est liée à l’autonomie de la volonté rationnelle.'],['Sartre','L’existentialisme insiste sur la responsabilité du sujet et ses choix.']], [['Suis-je libre si je suis déterminé ?','La loi limite-t-elle ou garantit-elle la liberté ?','Être libre, est-ce faire ce que l’on veut ?']], [q('L’autonomie désigne…',['La capacité de se donner une loi rationnelle','L’absence de toute règle','L’obéissance aveugle'],0,'L’autonomie est la capacité de se gouverner par une loi que la raison reconnaît.')]],
['nature','La nature','Physis, culture et environnement','La nature peut désigner l’ensemble du monde non produit par l’être humain, l’essence d’une chose ou ce qui est inné. Elle s’oppose parfois à la culture, mais les frontières entre les deux sont complexes.',[['Nature et culture',['La nature renvoie à ce qui existe indépendamment de l’intervention humaine ; la culture désigne les acquis transmis par l’éducation et la vie sociale.','L’être humain transforme son environnement, mais reste un être vivant dépendant de conditions naturelles. La culture n’abolit pas la nature : elle médiatise notre rapport au monde.']],['Maîtriser ou respecter la nature',['La technique permet de transformer les milieux et de répondre à des besoins, mais elle peut produire des effets irréversibles.','Les débats écologiques interrogent la valeur de la nature : ressource pour les humains, ensemble d’écosystèmes ou réalité ayant une valeur propre.']]], [['Nature','Ensemble des réalités non produites par l’activité humaine, ou essence d’un être.'],['Culture','Ensemble des acquis, normes et pratiques transmis socialement.'],['Nécessité naturelle','Ce qui relève de lois ou de contraintes naturelles.'],['Écologie','Étude des relations entre les êtres vivants et leur environnement.']], [['Rousseau','Discours sur l’origine et les fondements de l’inégalité : réflexion sur l’état de nature et la société.'],['Descartes','La technique permet de devenir comme maîtres et possesseurs de la nature (formule du Discours de la méthode).'],['Hans Jonas','Le Principe responsabilité : penser les effets à long terme de la puissance technique.']], [['La culture nous éloigne-t-elle de la nature ?','L’homme doit-il maîtriser la nature ?','La nature a-t-elle une valeur indépendante de l’homme ?']], [q('La culture désigne principalement…',['Les acquis et pratiques transmis socialement','Uniquement les phénomènes biologiques','Les lois physiques'],0,'La culture rassemble des pratiques, normes et savoirs acquis dans la vie sociale.')]],
['raison','La raison','Rationalité, démonstration et croyance','La raison est la faculté de penser selon des principes, d’établir des relations et de justifier des jugements. Elle permet de distinguer une démonstration d’une opinion, mais son usage rencontre des limites.',[['Raison et connaissance',['La raison organise les informations, construit des concepts et tire des conclusions. Le raisonnement déductif part de prémisses pour établir une conclusion ; l’induction généralise à partir de cas observés.','La démonstration exige des règles de validité. Une conclusion peut être logiquement valide sans que ses prémisses soient vraies.']],['Raison et expérience',['L’empirisme insiste sur le rôle de l’expérience sensible dans la connaissance ; le rationalisme souligne le rôle des principes et opérations de la raison.','La science articule observation, hypothèses, expérimentation et discussion critique. La raison n’est pas l’opposé de toute expérience : elle en organise l’interprétation.']],['Limites et usages',['La raison peut être mobilisée pour justifier des croyances préalables ou des intérêts. Les biais cognitifs et les passions influencent le jugement.','La rationalité pratique concerne les choix et les moyens d’agir ; elle ne détermine pas toujours à elle seule les fins à poursuivre.']]], [['Rationalité','Capacité à raisonner de manière cohérente et justifiable.'],['Déduction','Raisonnement allant de principes ou prémisses à une conclusion.'],['Induction','Généralisation à partir d’observations particulières.'],['Démonstration','Établissement rigoureux d’une conclusion à partir de règles et prémisses.']], [['Descartes','Discours de la méthode : recherche d’une méthode rationnelle.'],['Hume','Enquête sur l’entendement humain : rôle de l’expérience et critique de la causalité nécessaire.'],['Kant','Critique de la raison pure : examen des conditions et limites de la connaissance.']], [['La raison peut-elle tout connaître ?','La raison s’oppose-t-elle aux passions ?','L’expérience suffit-elle à produire une connaissance ?']], [q('La déduction consiste à…',['Tirer une conclusion à partir de prémisses','Généraliser sans observation','Remplacer toute preuve par une intuition'],0,'La déduction suit des règles logiques à partir de prémisses.')]],
['religion','La religion','Foi, croyance et sacré','La religion désigne un ensemble de croyances, de rites et d’institutions qui organisent le rapport au sacré et au divin. Elle peut structurer une communauté, donner du sens à l’existence et faire l’objet d’une critique rationnelle.',[['Foi et raison',['La foi est une adhésion à des vérités religieuses qui ne repose pas nécessairement sur une démonstration rationnelle. La raison peut examiner les arguments, les textes et les conséquences des croyances.','Certaines philosophies cherchent à articuler foi et raison ; d’autres considèrent qu’elles relèvent de domaines distincts ou entrent en tension.']],['Religion et société',['Durkheim analyse la religion comme un fait social qui distingue sacré et profane et renforce la cohésion collective par les rites.','Marx interprète la religion dans le contexte des rapports sociaux et des souffrances ; Freud l’analyse comme une illusion liée aux désirs et aux besoins psychiques.']],['Critique et tolérance',['La liberté de conscience suppose le droit de croire, de ne pas croire et de changer de conviction. La laïcité organise la neutralité de l’État et la liberté de conscience dans le cadre juridique français.']]], [['Sacré','Ce qui est séparé du profane et fait l’objet d’un respect particulier.'],['Foi','Adhésion à une croyance religieuse.'],['Rite','Pratique codifiée à dimension symbolique ou religieuse.'],['Laïcité','Principe organisant la neutralité de l’État et la liberté de conscience.']], [['Durkheim','Les Formes élémentaires de la vie religieuse (1912) : religion et cohésion sociale.'],['Marx','Critique de la religion dans l’analyse des rapports sociaux.'],['Freud','L’Avenir d’une illusion (1927) : interprétation psychique de la croyance religieuse.'],['Spinoza','Traité théologico-politique : examen critique des textes et de la liberté de philosopher.']], [['La religion répond-elle à un besoin humain ?','Foi et raison sont-elles incompatibles ?','La religion est-elle nécessaire à la cohésion sociale ?']], [q('Pour Durkheim, la religion est notamment…',['Un fait social qui organise le rapport au sacré','Une simple décision individuelle sans dimension collective','Une théorie économique'],0,'Durkheim étudie les rites et croyances comme des faits sociaux.')]],
['science','La science','Vérité, méthode et progrès','La science est une démarche organisée de production de connaissances qui s’appuie sur des méthodes explicites, des preuves, des tests et une discussion collective. Elle se distingue de l’opinion par ses procédures de justification.',[['La démarche scientifique',['Une hypothèse scientifique doit pouvoir être confrontée à l’observation ou à l’expérience selon les méthodes de la discipline. Les résultats sont discutés, reproduits et révisés.','La science ne consiste pas à accumuler des faits sans théorie : les concepts et modèles orientent les observations, qui peuvent en retour conduire à les modifier.']],['Vérité et réfutabilité',['Popper propose la falsifiabilité comme critère de démarcation : une théorie scientifique doit exposer ce qui pourrait la mettre en défaut.','Kuhn montre que les sciences connaissent des périodes de science normale et des révolutions scientifiques où les cadres théoriques changent.']],['Science et société',['Les applications scientifiques posent des questions éthiques et politiques. Les experts éclairent les décisions, mais les choix collectifs ne sont pas uniquement techniques.','La confiance scientifique dépend de la transparence, de l’indépendance, de la qualité des méthodes et de la capacité à reconnaître l’incertitude.']]], [['Hypothèse','Proposition provisoire soumise à l’épreuve de l’enquête.'],['Falsifiabilité','Possibilité de concevoir une observation qui pourrait réfuter une théorie.'],['Paradigme','Cadre théorique et méthodologique partagé par une communauté scientifique.'],['Vulgarisation','Transmission de connaissances spécialisées à un public non spécialiste.']], [['Popper','La Logique de la découverte scientifique (1934) : falsifiabilité.'],['Kuhn','La Structure des révolutions scientifiques (1962) : paradigmes et révolutions.'],['Bachelard','La Formation de l’esprit scientifique (1938) : rupture avec les obstacles épistémologiques.']], [['La science produit-elle des vérités définitives ?','La science peut-elle être neutre ?','Qu’est-ce qui distingue savoir et opinion ?']], [q('La falsifiabilité est associée à…',['Karl Popper','Émile Durkheim','Jean-Jacques Rousseau'],0,'Pour Popper, une théorie scientifique doit pouvoir être mise à l’épreuve et potentiellement réfutée.')]],
['technique','La technique','Outils, maîtrise et responsabilité','La technique désigne les procédés et savoir-faire permettant de produire des effets et de transformer le monde. Elle augmente les capacités humaines, mais modifie aussi les conditions de vie et les rapports de pouvoir.',[['Technique et humanité',['La technique prolonge les capacités du corps et permet de répondre à des besoins. Elle est constitutive des sociétés humaines, et pas seulement un ensemble d’objets modernes.','La technique transforme les milieux et les relations sociales. Les innovations peuvent libérer de certaines tâches tout en créant de nouvelles dépendances.']],['Progrès et ambivalence',['Le progrès technique peut améliorer la santé, la mobilité et la production, mais ses effets ne sont pas automatiquement bénéfiques ni équitablement répartis.','Heidegger interroge la manière dont la technique moderne transforme le rapport au monde en le présentant comme un stock de ressources disponibles.']],['Responsabilité',['Jonas insiste sur la puissance nouvelle des techniques et la nécessité d’anticiper leurs effets à long terme sur les générations futures et le vivant.','L’évaluation d’une innovation doit considérer ses risques, ses usages, ses effets sociaux et les conditions de son contrôle démocratique.']]], [['Technique','Ensemble de procédés et savoir-faire permettant d’agir efficacement sur le monde.'],['Outil','Moyen matériel utilisé pour réaliser une action.'],['Innovation','Introduction d’une nouveauté dans un produit, procédé ou organisation.'],['Responsabilité','Obligation de répondre de ses actes et de leurs conséquences.']], [['Descartes','La technique peut accroître la maîtrise humaine de la nature.'],['Heidegger','La Question de la technique : critique du dévoilement du monde comme fonds disponible.'],['Hans Jonas','Le Principe responsabilité (1979) : responsabilité face aux effets lointains de la technique.']], [['Le progrès technique rend-il l’homme plus libre ?','Peut-on maîtriser les effets de la technique ?','Le progrès technique est-il toujours un progrès humain ?']], [q('Hans Jonas insiste surtout sur…',['La responsabilité face aux effets à long terme de la technique','L’absence de conséquences des innovations','La supériorité de la force physique'],0,'Jonas souligne que la puissance technique impose une responsabilité envers l’avenir.')]],
['temps','Le temps','Passé, présent, avenir et durée','Le temps est la dimension dans laquelle les événements se succèdent et changent. Il peut être mesuré par les horloges, vécu subjectivement et pensé comme durée, devenir ou éternité.',[['Temps mesuré et temps vécu',['Le temps objectif est mesuré par des unités conventionnelles ; le temps vécu varie selon l’attention, l’attente, le plaisir ou l’ennui.','Bergson distingue le temps homogène des horloges et la durée vécue, qualitative et continue.']],['Mémoire et histoire',['Le passé n’existe plus comme présent, mais il demeure par la mémoire, les traces et les récits. La mémoire personnelle participe à l’identité, tandis que l’histoire construit une connaissance critique du passé.','L’oubli peut être une perte, mais aussi une condition de la vie psychique et de la sélection des souvenirs.']],['Avenir et finitude',['L’avenir ouvre un champ de possibilités, mais il est incertain. La conscience de la finitude donne une importance particulière aux choix et aux projets.','La manière de se rapporter au temps influence l’action : attendre, prévoir, regretter ou promettre sont des attitudes différentes.']]], [['Temps objectif','Temps mesuré selon des unités communes.'],['Durée','Temps vécu comme continuité qualitative.'],['Mémoire','Faculté de conserver et de rappeler des expériences passées.'],['Finitude','Caractère limité de l’existence humaine.']], [['Bergson','Essai sur les données immédiates de la conscience : analyse de la durée.'],['Saint Augustin','Les Confessions : réflexion sur le passé, le présent et l’avenir.'],['Heidegger','Être et Temps : temporalité et existence humaine.']], [['Le temps existe-t-il indépendamment de nous ?','Peut-on vivre sans se souvenir ?','La conscience de la mort donne-t-elle un sens à la vie ?']], [q('Bergson distingue notamment…',['Temps mesuré et durée vécue','Nature et culture uniquement','Droit et morale'],0,'Bergson analyse la durée comme expérience qualitative du temps.')]],
['travail','Le travail','Production, transformation et émancipation','Le travail est une activité par laquelle les humains transforment la nature et produisent des biens ou services. Il peut être une nécessité, une source d’identité et de reconnaissance, mais aussi une contrainte et une exploitation.',[['Travail et humanisation',['Le travail transforme le monde et transforme aussi celui qui travaille : il mobilise des savoir-faire, une organisation et une coopération.','Hegel analyse le travail comme médiation par laquelle la conscience transforme la nature et se forme elle-même.']],['Travail et aliénation',['Marx distingue la capacité humaine de produire de manière consciente et les formes historiques du travail salarié. Dans le capitalisme, le travailleur peut être dépossédé du produit, du processus et du sens de son activité.','La division du travail peut accroître la productivité mais réduire l’autonomie et fragmenter les tâches.']],['Travail et liberté',['Le travail peut permettre l’indépendance matérielle et la participation sociale, mais il peut aussi être subi. Les conditions, le temps, la reconnaissance et le pouvoir d’agir influencent son sens.']]], [['Travail','Activité productive qui transforme la nature et produit des biens ou services.'],['Aliénation','Situation dans laquelle un individu est dépossédé du sens ou du contrôle de son activité.'],['Division du travail','Répartition des tâches entre individus ou groupes.'],['Reconnaissance','Attribution d’une valeur sociale à une activité ou à une personne.']], [['Hegel','La dialectique du maître et de l’esclave analyse la formation de soi par le travail.'],['Marx','Manuscrits de 1844 et Le Capital : analyse de l’aliénation et des rapports de production.'],['Simone Weil','Réflexions sur les conditions concrètes du travail ouvrier.']], [['Le travail est-il une contrainte ou une liberté ?','Le travail permet-il de se réaliser ?','La division du travail déshumanise-t-elle ?']], [q('L’aliénation du travail est notamment analysée par…',['Karl Marx','David Ricardo uniquement','Aristote uniquement'],0,'Marx analyse la dépossession du travailleur dans les rapports de production capitalistes.')]],
['verite','La vérité','Opinion, preuve et connaissance','La vérité désigne le caractère d’un jugement conforme à ce qui est. La recherche de la vérité suppose de distinguer opinion, croyance, erreur et savoir, et d’examiner les critères de justification.',[['Opinion et connaissance',['L’opinion est un jugement souvent admis sans examen suffisant. Elle peut être vraie par hasard, mais ne constitue pas à elle seule un savoir justifié.','La vérité ne se confond pas avec le consensus : une idée peut être majoritaire et fausse, ou minoritaire et mieux fondée.']],['Critères de vérité',['La démonstration établit une conclusion selon des règles logiques ; l’expérience confronte les hypothèses aux faits ; la cohérence vérifie la compatibilité d’un ensemble de propositions.','Les sciences construisent des connaissances révisables et contrôlées. Reconnaître leur caractère provisoire ne revient pas à dire que toutes les affirmations se valent.']],['Vérité et pouvoir',['La parole peut chercher à convaincre plutôt qu’à établir le vrai. La propagande et la désinformation exploitent les émotions, les répétitions et les biais.','La recherche de la vérité suppose des institutions et pratiques : liberté d’enquête, débat contradictoire, accès aux sources et éducation critique.']]], [['Vérité','Caractère d’un jugement conforme à ce qui est.'],['Opinion','Jugement non suffisamment justifié ou examiné.'],['Erreur','Jugement faux tenu pour vrai.'],['Démonstration','Raisonnement établissant une conclusion selon des règles.'],['Relativisme','Position selon laquelle la vérité dépendrait du point de vue ou du cadre considéré.']], [['Platon','Allégorie de la caverne : passage de l’opinion à la connaissance.'],['Descartes','Discours de la méthode : doute méthodique et recherche de certitude.'],['Nietzsche','Interroge les rapports entre vérité, interprétation et valeurs.'],['Popper','La connaissance scientifique progresse par conjectures et réfutations.']], [['Peut-on se contenter de l’opinion ?','La vérité dépend-elle de nous ?','Toutes les vérités sont-elles démontrables ?']], [q('Une opinion se distingue d’un savoir car…',['Elle n’est pas nécessairement justifiée par une méthode critique','Elle est toujours fausse','Elle est toujours scientifique'],0,'Une opinion peut être vraie, mais elle ne repose pas nécessairement sur une justification solide.')]]
];
for(const d of philoData){const [id,title,subtitle,intro,sections,notions,examples,problems,quiz]=d;addCourse('philo',id,title,subtitle,intro,sections,notions,examples,problems.map((p,i)=>['Problématique '+(i+1),p]),quiz);}

// Quiz renforcés : définitions, mobilisation d'exemples et transfert des notions.
// Chaque chapitre possède un entraînement plus long, avec des questions contextualisées.
for(const data of Object.values(library)){
  const pool=data.notions||[];
  for(let i=0;i<Math.min(3,pool.length);i++){
    const [term,definition]=pool[i];
    const distractors=pool.filter((n,j)=>j!==i).slice(0,2).map(n=>n[1]);
    const answerIndex=i%3;const options=[...distractors];options.splice(answerIndex,0,definition);
    data.quiz.push(q(`Quelle définition correspond à « ${term} » ?`,options,answerIndex,`${term} : ${definition}`));
  }
  // Mobilisation des études de cas : retrouver le bon exemple à partir de sa description.
  const cases=data.examples||[];
  for(let i=0;i<Math.min(3,cases.length);i++){
    const [label,description]=cases[i];
    const distractors=cases.filter((x,j)=>j!==i).slice(0,2).map(x=>x[0]);
    if(distractors.length<2&&pool.length){const extra=pool.find(n=>n[0]!==label)?.[0];if(extra)distractors.push(extra);}
    if(distractors.length===2){
      const answerIndex=(i+1)%3;const options=[...distractors];options.splice(answerIndex,0,label);
      data.quiz.push(q(`Quel exemple correspond à la situation suivante : « ${description} » ?`,options,answerIndex,`${label} : ${description}`));
    }
  }
  // Questions de compréhension appliquée à partir des paragraphes du cours.
  const sections=data.sections||[];
  for(let i=0;i<Math.min(3,sections.length);i++){
    const [sectionTitle,paragraphs]=sections[i];
    const paragraph=Array.isArray(paragraphs)?paragraphs[0]:'';
    const otherTitles=sections.filter((x,j)=>j!==i).slice(0,2).map(x=>x[0]);
    if(otherTitles.length<2)otherTitles.push('Aucune de ces parties');
    if(paragraph&&otherTitles.length===2){
      const answerIndex=i%3;const options=[...otherTitles];options.splice(answerIndex,0,sectionTitle);
      const excerpt=paragraph.length>230?paragraph.slice(0,227).trimEnd()+'…':paragraph;
      data.quiz.push(q(`À quelle partie du cours rattacher cette idée : « ${excerpt} » ?`,options,answerIndex,`Cette idée relève de « ${sectionTitle} ». Relis cette partie pour retrouver les notions et les exemples associés.`));
    }
  }
  // Vérification de la capacité à reconnaître une notion dans une situation décrite.
  for(let i=0;i<Math.min(3,pool.length);i++){
    const [term,definition]=pool[i];
    const distractors=pool.filter((n,j)=>j!==i).slice(0,2).map(n=>n[0]);
    if(distractors.length===2){
      const answerIndex=(i+2)%3;const options=[...distractors];options.splice(answerIndex,0,term);
      data.quiz.push(q(`Quelle notion désigne précisément : « ${definition} » ?`,options,answerIndex,`${term} : ${definition}`));
    }
  }
  const synthesis=data.sheet||[];
  for(let j=0;data.quiz.length<10&&j<synthesis.length;j++){
    const target=synthesis[j],distractors=synthesis.filter((x,k)=>k!==j).slice(0,2).map(x=>x[0]);
    if(distractors.length===2){const options=[distractors[0],target[0],distractors[1]];data.quiz.push(q(`Quel point de synthèse correspond à cette explication : « ${target[1]} » ?`,options,1,`${target[0]} : ${target[1]}`));}
  }
}

