const originalRenderChapterTab=renderChapterTab;
renderChapterTab=function(){
  if(currentSubject==='hggsp'&&currentChapter.id==='conquete'){originalRenderChapterTab();return;}
  const data=library[currentSubject+':'+currentChapter.id];const el=document.querySelector('#chapter-content');
  if(!data){el.innerHTML='<div class="notice"><b>Contenu manquant</b><p>Cette fiche n’est pas disponible.</p></div>';return;}
  if(currentTab==='course'){
    el.innerHTML=`<div class="course-meta"><span class="eyebrow">COURS DE TERMINALE</span><p class="course-intro">${data.intro}</p></div>${data.sections.map(s=>`<h3>${s[0]}</h3>${s[1].map(p=>`<p>${p}</p>`).join('')}`).join('')}<h3>Notions essentielles</h3><div class="notion-grid">${data.notions.map(n=>`<div class="notion-card"><b>${n[0]}</b><p>${n[1]}</p></div>`).join('')}</div><h3>Repères et auteurs</h3>${data.examples.map(e=>`<div class="example-item"><b>${e[0]}</b><p>${e[1]}</p></div>`).join('')}<div class="notice"><b>Question directrice</b><p>${data.sheet[0]?.[1]||'Comment articuler les notions et les exemples de ce chapitre ?'}</p></div><button class="primary-btn" data-tab="sheet">Voir la fiche de révision →</button>`;
  } else if(currentTab==='sheet'){
    el.innerHTML=`<h3>Fiche de révision — L’essentiel</h3><p class="sheet-lead">${data.intro}</p>${data.sheet.map(x=>`<div class="sheet-point"><b>${x[0]}</b><p>${x[1]}</p></div>`).join('')}<h3>Notions à mémoriser</h3><div class="notion-grid">${data.notions.map(n=>`<div class="notion-card"><b>${n[0]}</b><p>${n[1]}</p></div>`).join('')}</div><h3>Exemples à mobiliser</h3>${data.examples.map(e=>`<div class="example-item"><b>${e[0]}</b><p>${e[1]}</p></div>`).join('')}<button class="primary-btn" data-tab="quiz">Je m’entraîne →</button>`;
  } else {
    el.innerHTML=`<h3>Quiz — ${data.title}</h3><p>${data.quiz.length} questions avec correction expliquée. Une bonne réponse rapporte 10 étoiles.</p><div class="quiz-start-card"><span>🎯</span><div><b>Prête à tester tes connaissances ?</b><p>Lis bien chaque question et prends le temps de comprendre la correction.</p></div></div><button class="primary-btn" id="start-chapter-quiz">Lancer le quiz →</button>`;
    document.querySelector('#start-chapter-quiz').addEventListener('click',()=>{activeQuestions=shuffleQuizQuestions(data.quiz);quizIndex=0;quizScore=0;renderQuestion();});
  }
};

// Adapter la validation des quiz à chaque chapitre.
finishQuiz=function(){
  state.review=state.review||[];state.done=state.done||[];state.quizzes++;const key=currentSubject+'-'+currentChapter.id;if(!state.done.includes(key))state.done.push(key);
  if(quizScore===activeQuestions.length){state.review=state.review.filter(x=>!activeQuestions.some(q=>q.q===x));}
  save();
  document.querySelector('#chapter-content').innerHTML=`<div style="text-align:center;padding:20px"><div style="font-size:48px">🌟</div><h3>Bravo, quiz terminé !</h3><p>Tu as obtenu <b>${quizScore} / ${activeQuestions.length}</b>.</p><p>${quizScore===activeQuestions.length?'Excellent travail !':'Chaque erreur est une occasion de progresser.'}</p><button class="primary-btn" id="replay-quiz">Recommencer</button></div>`;
  document.querySelector('#replay-quiz').addEventListener('click',()=>{quizIndex=0;quizScore=0;renderQuestion();});
};
