/* Chapitre SES manquant dans la première bibliothèque : justice sociale et inégalités. */
addCourse('ses','inegalites','Quelles inégalités sont compatibles avec les différentes conceptions de la justice sociale ?','Égalité, équité et redistribution',
'Les inégalités sont des différences d’accès à des ressources socialement valorisées qui créent des avantages ou des désavantages. La justice sociale interroge les inégalités considérées comme acceptables, les principes qui les justifient et les politiques permettant de les réduire.',[
['1. Définir et mesurer les inégalités',['Une inégalité est une différence entre individus ou groupes qui se traduit par un accès inégal à des ressources valorisées : revenus, patrimoine, diplômes, santé, pouvoir ou prestige. Elle est socialement construite et peut se cumuler.','Les inégalités économiques concernent notamment les revenus et le patrimoine. Les inégalités sociales touchent aussi les conditions de vie, la santé, la culture, le logement et la participation politique.','Les inégalités se mesurent à l’aide de distributions, de rapports interdéciles, de courbes de Lorenz ou du coefficient de Gini. Aucun indicateur isolé ne décrit toutes les dimensions de la justice sociale.']],
['2. Les différentes conceptions de la justice sociale',['L’égalité des droits garantit les mêmes droits fondamentaux ; l’égalité des chances vise à rendre les positions accessibles indépendamment de l’origine sociale ; l’égalité des situations cherche à réduire les écarts de conditions de vie.','La conception méritocratique accepte certaines inégalités si elles résultent de différences d’effort ou de contribution, à condition que les chances soient équitables. Elle suppose toutefois de discuter les inégalités de départ et les conditions réelles de la compétition.','John Rawls défend des libertés fondamentales égales et le principe de différence : les inégalités socio-économiques ne sont justifiables que si elles bénéficient aux plus désavantagés, dans un cadre d’égalité équitable des chances.']],
['3. Les instruments de la justice sociale',['La redistribution verticale réduit les écarts de revenus entre ménages ; la redistribution horizontale couvre des risques sociaux au cours de la vie, par exemple maladie, vieillesse ou chômage.','Les prélèvements obligatoires financent les prestations et services collectifs. Les impôts peuvent être progressifs, proportionnels ou forfaitaires ; les prestations peuvent être contributives ou non contributives.','Les services publics, l’éducation, la santé, les politiques d’emploi et la lutte contre les discriminations agissent aussi sur les inégalités. Chaque instrument soulève des débats sur son efficacité, son financement, ses effets incitatifs et son acceptabilité.']],
['4. Débats et limites',['Une politique peut réduire les inégalités de revenus sans supprimer les inégalités de patrimoine, de santé ou de réussite scolaire. Il faut donc distinguer égalité formelle et égalité réelle.','Les politiques de redistribution peuvent être contestées au nom de la liberté individuelle, de l’efficacité économique ou du risque de désincitation. À l’inverse, les inégalités trop fortes peuvent limiter la mobilité sociale et fragiliser la cohésion.','La justice sociale ne consiste pas nécessairement à rendre toutes les situations identiques : elle suppose de justifier les différences et d’examiner si les institutions garantissent des droits, des chances et des conditions de vie dignes.']]
],[['Inégalité','Différence d’accès à une ressource valorisée qui crée un avantage ou un désavantage.'],['Égalité des droits','Garantie des mêmes droits fondamentaux pour tous.'],['Égalité des chances','Principe selon lequel l’origine sociale ne doit pas déterminer l’accès aux positions.'],['Égalité des situations','Réduction des écarts de conditions de vie et de ressources.'],['Redistribution','Ensemble des prélèvements et prestations qui modifient la répartition des revenus.'],['Redistribution verticale','Transferts visant à réduire les écarts entre niveaux de revenus.'],['Redistribution horizontale','Transferts qui couvrent des risques sociaux au cours de la vie.'],['Justice sociale','Ensemble des principes permettant d’évaluer la répartition des droits, ressources et positions.']],
[['John Rawls','Théorie de la justice (1971) : libertés égales, égalité équitable des chances et principe de différence.'],['Coefficient de Gini','Indicateur synthétique des inégalités de répartition ; plus il est élevé, plus la distribution est inégalitaire.'],['Impôt progressif','Prélèvement dont le taux augmente avec la base imposable.'],['Services publics','L’éducation, la santé et les transports collectifs peuvent réduire les inégalités d’accès aux ressources.']],
[['Distinguer','Égalité des droits, égalité des chances et égalité des situations.'],['Justifier','Les inégalités sont-elles légitimes si elles récompensent le mérite ?'],['Redistribuer','La redistribution verticale réduit les écarts ; la redistribution horizontale couvre des risques.'],['Nuancer','La justice sociale ne signifie pas nécessairement l’identité de toutes les situations.']],
[q('Le principe de différence est associé à…',['John Rawls','Adam Smith','Auguste Comte'],0,'Rawls admet certaines inégalités si elles améliorent la situation des plus désavantagés.'),q('La redistribution horizontale vise principalement à…',['Couvrir les risques sociaux au cours de la vie','Réduire uniquement les écarts entre riches et pauvres','Financer les exportations'],0,'Elle mutualise des risques comme la maladie, la vieillesse ou le chômage.'),q('L’égalité des chances cherche à…',['Rendre les positions accessibles indépendamment de l’origine sociale','Rendre tous les revenus identiques','Supprimer les droits individuels'],0,'Elle vise à limiter l’effet de l’origine sur les trajectoires.')]
);

/* Navigation complète : les chapitres détaillés ci-dessus alimentent les listes de matières. */
subjects.ses.chapters = [
 {id:'croissance',title:'Quelles sont les sources et les défis de la croissance économique ?',subtitle:'Productivité, progrès technique et limites'},
 {id:'commerce',title:'Quels sont les fondements du commerce international et de l’internationalisation de la production ?',subtitle:'Spécialisation, échanges et chaînes de valeur'},
 {id:'emploi',title:'Comment lutter contre le chômage ?',subtitle:'Marché du travail et politiques de l’emploi'},
 {id:'crises',title:'Comment expliquer les crises financières et réguler le système financier ?',subtitle:'Instabilité, contagion et régulation'},
 {id:'action',title:'Quelles politiques économiques dans le cadre européen ?',subtitle:'Politiques conjoncturelles et intégration européenne'},
 {id:'structure',title:'Comment est structurée la société française actuelle ?',subtitle:'Groupes sociaux, hiérarchies et facteurs de différenciation'},
 {id:'ecole',title:'Quelle est l’action de l’École sur les destins individuels et sur l’évolution de la société ?',subtitle:'Massification, démocratisation et inégalités scolaires'},
 {id:'mobilite',title:'Quelles sont les caractéristiques contemporaines et les facteurs de la mobilité sociale ?',subtitle:'Trajectoires, fluidité et reproduction sociale'},
 {id:'travail',title:'Quelles mutations du travail et de l’emploi ?',subtitle:'Organisation du travail, qualité de l’emploi et transformations'},
 {id:'engagement',title:'Comment expliquer l’engagement politique dans les sociétés démocratiques ?',subtitle:'Participation, répertoires d’action et déterminants'},
 {id:'inegalites',title:'Quelles inégalités sont compatibles avec les différentes conceptions de la justice sociale ?',subtitle:'Égalité, équité et redistribution'},
 {id:'environnement',title:'Quelle action publique pour l’environnement ?',subtitle:'Défaillances de marché, instruments et gouvernance'}
];
subjects.philo.chapters = philoTitles.map(([id,title,subtitle])=>({id,title,subtitle}));

/* Fiches structurées : synthèse, plan, notions, références et questions de réflexion. */
const previousRenderChapterTab = renderChapterTab;
function ficheEscape(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function ficheSectionRows(data){
 return (data.sections||[]).map((sec,i)=>{
   const heading=Array.isArray(sec)?sec[0]:(sec.title||('Partie '+(i+1)));
   const paragraphs=Array.isArray(sec)?(sec[1]||[]):(sec.paragraphs||[]);
   return {heading,paragraphs,summary:paragraphs.slice(0,2).join(' ')};
 });
}
function renderCompleteFiche(data,subject){
 const isPhilo=subject==='philo';
 const sections=ficheSectionRows(data);
 const sheet=Array.isArray(data.sheet)?data.sheet:[];
 const isProblematic=isPhilo;
 const summaryCards=(!isProblematic && sheet.length)
   ? sheet.map((x,i)=>`<article class="revision-card revision-card-${i%4}"><span class="revision-kicker">À RETENIR ${String(i+1).padStart(2,'0')}</span><h4>${ficheEscape(x[0])}</h4><p>${ficheEscape(x[1])}</p></article>`).join('')
   : sections.map((x,i)=>`<article class="revision-card revision-card-${i%4}"><span class="revision-kicker">IDÉE ${String(i+1).padStart(2,'0')}</span><h4>${ficheEscape(x.heading)}</h4><p>${ficheEscape(x.summary)}</p></article>`).join('');
 const detailedSections=sections.map((sec,i)=>`<details class="revision-deep-dive"><summary><span>${String(i+1).padStart(2,'0')}</span>${ficheEscape(sec.heading)}</summary><div>${sec.paragraphs.map(p=>`<p>${ficheEscape(p)}</p>`).join('')}</div></details>`).join('');
 const notions=(data.notions||[]).map((n,i)=>`<article class="revision-term revision-term-${i%4}"><b>${ficheEscape(n[0])}</b><p>${ficheEscape(n[1])}</p></article>`).join('');
 const refs=(data.examples||[]).map((x,i)=>`<article class="revision-reference"><b>${ficheEscape(x[0])}</b><p>${ficheEscape(x[1])}</p></article>`).join('');
 const questions= isProblematic ? sheet.map(x=>`<li>${ficheEscape(x[1])}</li>`).join('') : '';
 return `<div class="revision-sheet">
   <div class="revision-sheet-top"><span class="revision-sticker">✦ FICHE EXPRESS</span><span class="revision-subject">${isPhilo?'PHILOSOPHIE':subject==='ses'?'SES':'HGGSP'}</span></div>
   <h3>À connaître pour le bac</h3><p class="revision-lead">${ficheEscape(data.intro)}</p>
   <div class="revision-section-head"><span>01</span><div><b>Les idées essentielles</b><small>Le fil directeur du chapitre</small></div></div>
   <div class="revision-card-grid">${summaryCards}</div>
   <div class="revision-section-head"><span>02</span><div><b>Le cours détaillé à revoir</b><small>Ouvre chaque partie pour retrouver les explications complètes</small></div></div>
   <div class="revision-deep-list">${detailedSections}</div>
   <div class="revision-section-head"><span>03</span><div><b>Les notions indispensables</b><small>Définitions à savoir expliquer et réutiliser</small></div></div>
   <div class="revision-term-grid">${notions}</div>
   <div class="revision-section-head"><span>04</span><div><b>${isPhilo?'Auteurs et références':'Exemples et repères'}</b><small>${isPhilo?'Thèses et œuvres à mobiliser avec précision':'Dates, acteurs, mécanismes et exemples concrets'}</small></div></div>
   <div class="revision-reference-grid">${refs}</div>
   ${isProblematic?`<div class="revision-question-box"><b>Problématiques possibles</b><ul>${questions}</ul></div>`:''}
   <div class="revision-method"><b>Réflexe de révision</b><p>${isPhilo?'Pour chaque notion, sache définir le concept, formuler une tension philosophique, expliquer au moins deux thèses et construire un exemple.':'Pour chaque idée, associe une définition précise, un mécanisme ou un enjeu, puis un exemple daté et contextualisé.'}</p></div>
   <button class="primary-btn" data-tab="quiz">Je vérifie ce que j’ai retenu →</button>
 </div>`;
}
renderChapterTab=function(){
 if(currentSubject==='hggsp'&&currentChapter?.id==='conquete'){
   if(currentTab==='sheet'){
     const d={intro:chapterOne.intro,sections:chapterOne.sections.map(s=>[s.title,s.paragraphs]),notions:chapterOne.notions,examples:chapterOne.examples,sheet:chapterOne.sheet};
     document.querySelector('#chapter-content').innerHTML=renderCompleteFiche(d,'hggsp');return;
   }
   previousRenderChapterTab();return;
 }
 const data=library[currentSubject+':'+currentChapter?.id];
 if(!data){document.querySelector('#chapter-content').innerHTML='<div class="notice"><b>Contenu indisponible</b><p>Cette partie doit être complétée avant de pouvoir être révisée.</p></div>';return;}
 if(currentTab==='sheet'){document.querySelector('#chapter-content').innerHTML=renderCompleteFiche(data,currentSubject);return;}
 previousRenderChapterTab();
};

// Compléments pédagogiques du thème 1 HGGSP.
chapterOne.sections.push(['6. Approfondissement : rivalités, droit et coopération',['Les espaces maritimes sont à la fois des espaces de circulation, de ressources et de puissance. Les routes maritimes concentrent une part majeure des échanges mondiaux ; les détroits et canaux constituent donc des points de passage stratégiques. Leur contrôle, leur sécurisation et la liberté de navigation peuvent opposer les intérêts des États riverains aux intérêts des puissances commerciales et navales.', 'La compétition spatiale ne se limite plus à la rivalité entre les États-Unis et l’URSS. Les puissances émergentes, les entreprises privées et les organisations de coopération interviennent désormais dans les lancements, les télécommunications, l’observation de la Terre et l’exploration. Il faut distinguer la puissance symbolique, les usages économiques et militaires, et les règles juridiques qui encadrent ces activités.']]);

if(library['hggsp:guerre-paix']) library['hggsp:guerre-paix'].sections.push(['Approfondissement — mécanismes et enjeux',['Les formes de guerre doivent être distinguées selon les acteurs, les objectifs, les moyens et les espaces concernés. Une guerre interétatique oppose des États ; une guerre civile se déroule au sein d’un État ; un conflit peut ensuite s’internationaliser par l’intervention de puissances étrangères. Les catégories ne sont pas toujours exclusives : un conflit interne peut devenir un affrontement régional ou international.',
'La paix ne se résume pas à la signature d’un traité. Il faut distinguer le cessez-le-feu, le règlement politique, les garanties de sécurité, la reconstruction et la réconciliation. Les accords peuvent être fragiles si certains acteurs sont exclus, si les causes politiques du conflit persistent ou si les institutions ne disposent pas de moyens pour faire appliquer les engagements.',
'La paix de Westphalie (1648) est souvent présentée comme un repère dans la construction de l’ordre international fondé sur les États et leur souveraineté. Il ne faut toutefois pas en faire l’origine unique et instantanée de l’État moderne : les pratiques diplomatiques et les équilibres de puissance se sont transformés progressivement.']]);

if(library['hggsp:memoire']) library['hggsp:memoire'].sections.push(['Approfondissement — mécanismes et enjeux',['Les politiques mémorielles sont des choix publics portant sur la reconnaissance, la commémoration et la transmission du passé. Elles peuvent contribuer à la cohésion nationale, mais aussi susciter des controverses lorsque des groupes demandent la reconnaissance d’expériences longtemps marginalisées. Les commémorations, les monuments, les programmes scolaires et les discours officiels sont autant de supports de mémoire.',
'Le travail de l’historien repose sur la critique des sources, leur confrontation et leur contextualisation. Un témoignage est précieux pour comprendre une expérience vécue, mais il doit être étudié comme une source située : date, conditions de production, intention et mémoire individuelle. L’histoire n’efface pas les mémoires ; elle les étudie et les met à distance.',
'La justice peut intervenir dans la sortie des violences par les procès, les commissions vérité, les réparations et les politiques de reconnaissance. Ces dispositifs répondent à des objectifs différents : établir des responsabilités individuelles, documenter les faits, reconnaître les victimes et favoriser une coexistence politique.']]);

if(library['hggsp:patrimoine']) library['hggsp:patrimoine'].sections.push(['Approfondissement — mécanismes et enjeux',['Le patrimoine est une construction sociale et politique : une société sélectionne certains objets, lieux, pratiques ou paysages pour les transmettre. Cette sélection évolue avec les valeurs et les usages. Le patrimoine peut être matériel, immatériel, naturel ou industriel ; il n’est donc pas limité aux monuments anciens.',
'La patrimonialisation peut renforcer l’attractivité touristique et le rayonnement culturel, mais elle crée aussi des tensions. La fréquentation touristique peut dégrader les sites, augmenter les prix et transformer les usages locaux. La conservation suppose alors des arbitrages entre protection, accès du public, activité économique et vie des habitants.',
'L’UNESCO apporte une reconnaissance internationale et encourage la coopération, mais l’inscription sur une liste ne garantit pas à elle seule la conservation. Les États et les acteurs locaux restent essentiels pour financer, réglementer, entretenir et transmettre les patrimoines.']]);

if(library['hggsp:environnement']) library['hggsp:environnement'].sections.push(['Approfondissement — mécanismes et enjeux',['Les ressources et les milieux sont l’objet de rivalités parce que leurs usages peuvent être concurrents et leurs effets dépasser les frontières. L’eau, les forêts, les sols, les ressources énergétiques et les espaces polaires mettent en relation des acteurs aux intérêts différents : États, entreprises, populations locales, scientifiques et organisations internationales.',
'La gouvernance environnementale s’est construite progressivement autour de conférences, de conventions et d’accords. Le Sommet de Rio de 1992, le Protocole de Kyoto de 1997 et l’Accord de Paris de 2015 constituent des repères importants, mais leurs objectifs, leurs mécanismes et leurs degrés de contrainte diffèrent. Il faut toujours distinguer l’adoption d’un accord de sa mise en œuvre effective.',
'Les politiques de protection peuvent entrer en tension avec les besoins de développement et les inégalités entre pays. La notion de développement durable cherche à articuler dimensions environnementale, économique et sociale ; la justice climatique interroge notamment la répartition des responsabilités historiques, des coûts de transition et des capacités d’adaptation.']]);

if(library['hggsp:connaissance']) library['hggsp:connaissance'].sections.push(['Approfondissement — mécanismes et enjeux',['La connaissance est une ressource stratégique : elle contribue à la puissance économique, scientifique, militaire et diplomatique. Les États cherchent à former une population qualifiée, financer la recherche, attirer les talents et protéger certaines innovations. Les entreprises investissent dans la recherche-développement et dans la maîtrise des données, des brevets et des infrastructures numériques.',
'La diffusion des savoirs dépend d’infrastructures et d’acteurs : écoles, universités, bibliothèques, médias, réseaux numériques, laboratoires et organisations internationales. L’accès à ces ressources est inégal selon les territoires et les groupes sociaux. La fracture numérique ne concerne pas seulement la connexion : elle touche aussi les équipements, les compétences et la capacité à vérifier l’information.',
'La circulation mondiale de l’information facilite la coopération scientifique, mais elle peut aussi accélérer la désinformation, les manipulations et les cyberattaques. Il faut donc distinguer liberté d’expression, fiabilité des sources, sécurité des systèmes et souveraineté numérique.']]);

if(library['ses:croissance']) library['ses:croissance'].sections.push(['Approfondissement — mécanismes et enjeux',['La croissance se mesure par l’évolution du produit intérieur brut en volume, c’est-à-dire corrigé de l’effet des prix. Le PIB permet de suivre la production marchande et une partie de la production non marchande, mais il ne mesure pas directement le bien-être, les inégalités, le travail domestique non rémunéré ni la soutenabilité environnementale.',
'L’accumulation des facteurs de production augmente les capacités productives, tandis que les gains de productivité permettent de produire davantage avec une même quantité de facteurs. Le progrès technique peut être incorporé dans le capital, améliorer l’organisation du travail ou créer de nouveaux produits. Les institutions, l’éducation, la recherche et les infrastructures influencent la capacité d’innovation.',
'La croissance rencontre des limites écologiques : émissions de gaz à effet de serre, épuisement de certaines ressources, artificialisation des sols et perte de biodiversité. Les innovations peuvent réduire certaines pressions, mais les effets rebond et l’augmentation des volumes produits peuvent limiter les gains environnementaux.']]);

if(library['ses:commerce']) library['ses:commerce'].sections.push(['Approfondissement — mécanismes et enjeux',['La spécialisation internationale repose notamment sur les avantages comparatifs : un pays peut avoir intérêt à se spécialiser dans les productions pour lesquelles son coût d’opportunité est relativement plus faible. Les dotations en facteurs, les technologies, la qualification du travail et les économies d’échelle contribuent à expliquer les échanges.',
'Le commerce international est aussi un commerce entre pays comparables, notamment par la différenciation des produits et la recherche de variété. Les entreprises fragmentent parfois leur chaîne de valeur entre plusieurs territoires afin de combiner coûts, compétences, proximité des marchés et accès aux fournisseurs.',
'Les gains à l’échange sont inégalement répartis. Les consommateurs peuvent bénéficier de prix plus faibles et d’une plus grande variété, tandis que certains secteurs et travailleurs subissent la concurrence. Les politiques d’accompagnement, de formation et de protection sociale influencent la capacité des économies à absorber ces transformations.']]);

if(library['ses:emploi']) library['ses:emploi'].sections.push(['Approfondissement — mécanismes et enjeux',['Le chômage au sens du BIT concerne une personne sans emploi, disponible pour travailler et en recherche active d’emploi. Il faut distinguer le chômage du halo autour du chômage, du sous-emploi et de l’inactivité : les indicateurs ne décrivent pas exactement les mêmes situations.',
'Le chômage conjoncturel est lié à une insuffisance de la demande globale ; le chômage structurel peut résulter d’inadéquations de qualifications, de difficultés d’appariement, de rigidités ou de transformations durables de l’économie. Le diagnostic est important car les politiques adaptées ne sont pas les mêmes.',
'Les politiques de l’emploi combinent soutien à l’activité, formation, accompagnement des demandeurs d’emploi, incitations à l’embauche et règles du marché du travail. Une mesure peut améliorer l’accès à l’emploi tout en soulevant des questions de coût budgétaire, de qualité des emplois ou d’effets d’aubaine.']]);

if(library['ses:crises']) library['ses:crises'].sections.push(['Approfondissement — mécanismes et enjeux',['Le système financier met en relation les agents qui disposent d’une capacité de financement et ceux qui ont un besoin de financement. Les banques transforment notamment des ressources à court terme en crédits plus longs et assurent des fonctions de paiement et de sélection des emprunteurs.',
'Une crise peut être alimentée par le crédit excessif, l’endettement, la hausse spéculative des prix d’actifs et l’opacité de certains produits financiers. Lorsqu’un acteur important rencontre des difficultés, les pertes et la défiance peuvent se transmettre à d’autres institutions : c’est le risque systémique.',
'La régulation associe exigences de fonds propres, surveillance prudentielle, garanties des dépôts, transparence et intervention des banques centrales. Elle cherche à limiter la prise de risque excessive sans empêcher le financement de l’économie.']]);

if(library['ses:action']) library['ses:action'].sections.push(['Approfondissement — mécanismes et enjeux',['La politique monétaire agit sur les conditions de financement et la stabilité des prix. Dans la zone euro, elle est conduite par la Banque centrale européenne, qui utilise notamment ses taux directeurs et des opérations sur les marchés. La politique budgétaire relève des gouvernements : dépenses publiques, prélèvements et transferts influencent la demande et l’activité.',
'L’intégration européenne crée des interdépendances : une décision nationale peut avoir des effets sur les partenaires, tandis que la monnaie unique implique une politique monétaire commune. Les États conservent des budgets nationaux, mais leurs choix sont encadrés par des règles et par la coordination européenne.',
'Les politiques conjoncturelles peuvent être contraintes par le niveau de dette, l’inflation, les règles communes et les délais de transmission. Il faut distinguer les objectifs de court terme — stabiliser l’activité et l’emploi — des politiques structurelles de long terme, qui visent la productivité et la compétitivité.']]);

if(library['ses:structure']) library['ses:structure'].sections.push(['Approfondissement — mécanismes et enjeux',['La structure sociale désigne la manière dont une société est organisée en groupes et en positions hiérarchisées. Elle peut être étudiée à partir de la profession, du revenu, du diplôme, du patrimoine, du genre, de l’âge, de la composition du ménage ou du lieu de résidence. Aucun critère isolé ne suffit à décrire toutes les positions sociales.',
'Les professions et catégories socioprofessionnelles permettent de regrouper des individus selon leur profession, leur statut et leur qualification. Cet outil est utile pour comparer des groupes, mais il ne faut pas confondre catégorie statistique et identité vécue : les groupes sont traversés par des différences internes.',
'Les transformations de la structure sociale sont liées à la salarisation, à la tertiarisation, à l’élévation des qualifications, à la féminisation de l’emploi et à l’évolution des modes de vie. Ces évolutions ne font pas disparaître les classes sociales : elles transforment les frontières et les formes de différenciation.']]);

if(library['ses:ecole']) library['ses:ecole'].sections.push(['Approfondissement — mécanismes et enjeux',['La massification scolaire correspond à l’allongement de la scolarité et à l’augmentation du nombre d’élèves scolarisés. La démocratisation suppose en plus une réduction des écarts de réussite et d’accès aux différentes filières selon l’origine sociale. Une hausse du niveau moyen de diplôme ne suffit donc pas à prouver l’égalité des chances.',
'Les ressources familiales influencent les parcours par les conditions matérielles, les pratiques culturelles, les attentes, l’information sur l’orientation et la familiarité avec les codes scolaires. Les travaux de Pierre Bourdieu et Jean-Claude Passeron soulignent notamment le rôle du capital culturel et des mécanismes de reproduction sociale.',
'L’École peut favoriser la mobilité sociale grâce aux savoirs, aux diplômes et aux concours, mais les inégalités de réussite et d’orientation persistent. L’analyse doit distinguer accès à l’école, réussite, choix des filières et valeur des diplômes sur le marché du travail.']]);

if(library['ses:mobilite']) library['ses:mobilite'].sections.push(['Approfondissement — mécanismes et enjeux',['La mobilité sociale désigne le changement de position sociale d’un individu ou d’un groupe. Elle peut être intergénérationnelle lorsqu’on compare la position des enfants à celle de leurs parents, ou intragénérationnelle lorsqu’on étudie la trajectoire d’une personne au cours de sa vie.',
'Les tables de mobilité permettent d’étudier la mobilité observée et la reproduction sociale. Il faut distinguer mobilité structurelle, liée à la transformation de la structure des emplois, et mobilité nette ou fluidité sociale, qui cherche à apprécier l’inégalité des chances de mobilité entre origines sociales.',
'Les diplômes, la transformation des emplois, la conjoncture économique, les ressources familiales et les politiques publiques influencent les trajectoires. Une mobilité ascendante individuelle ne signifie pas nécessairement que la société est devenue plus fluide : il faut examiner les chances relatives des différents groupes.']]);

if(library['ses:travail']) library['ses:travail'].sections.push(['Approfondissement — mécanismes et enjeux',['Le travail est une activité productive qui peut être rémunérée ou non ; l’emploi désigne une activité professionnelle déclarée et rémunérée dans un cadre institutionnel. Le salariat est une forme d’emploi caractérisée par un lien de subordination juridique et une rémunération.',
'L’organisation du travail a évolué du taylorisme et du fordisme vers des formes plus flexibles, avec polyvalence, travail en équipe, objectifs et outils numériques. Ces transformations peuvent accroître l’autonomie de certains salariés, mais aussi intensifier le travail, renforcer le contrôle et brouiller les frontières entre temps professionnel et temps personnel.',
'La qualité de l’emploi dépend notamment de la rémunération, de la stabilité, des conditions de travail, des horaires, de l’autonomie et des perspectives de carrière. La polarisation des emplois et le développement de formes atypiques invitent à ne pas réduire les mutations du travail à la seule numérisation.']]);

if(library['ses:engagement']) library['ses:engagement'].sections.push(['Approfondissement — mécanismes et enjeux',['La participation politique ne se limite pas au vote. Elle comprend l’adhésion à un parti ou à une association, le militantisme, les manifestations, les pétitions, les boycotts et les mobilisations numériques. Les répertoires d’action évoluent avec les technologies, les causes et les opportunités politiques.',
'L’engagement dépend de ressources inégalement réparties : temps, argent, compétences, réseaux et sentiment de légitimité. La socialisation politique, l’âge, le diplôme, la profession et les expériences collectives contribuent aussi aux formes de participation.',
'Le paradoxe de l’action collective souligne qu’un individu peut souhaiter bénéficier d’un résultat collectif sans supporter le coût de la mobilisation. Les organisations, les incitations sélectives, les solidarités et les identités collectives peuvent favoriser la participation.']]);

if(library['ses:inegalites']) library['ses:inegalites'].sections.push(['Approfondissement — mécanismes et enjeux',['Les conceptions de la justice sociale ne donnent pas toutes la même priorité à la liberté, à l’égalité, au mérite ou à la solidarité. L’égalité des droits est une condition fondamentale, mais elle ne garantit pas à elle seule une égalité réelle des chances lorsque les individus disposent de ressources de départ très différentes.',
'John Rawls propose de juger les institutions à partir de principes choisis dans une situation hypothétique d’impartialité : libertés fondamentales égales, égalité équitable des chances et principe de différence. Ce dernier autorise certaines inégalités si elles améliorent la situation des plus désavantagés.',
'La redistribution peut être verticale, lorsqu’elle réduit les écarts de ressources, ou horizontale, lorsqu’elle mutualise les risques sociaux. Elle passe par les prélèvements, les prestations et les services publics ; son évaluation doit considérer ses effets sur la pauvreté, les inégalités, l’accès aux droits et les incitations.']]);

if(library['ses:justice-sociale']) library['ses:justice-sociale'].sections.push(['Approfondissement — mécanismes et enjeux',['Les conceptions de la justice sociale ne donnent pas toutes la même priorité à la liberté, à l’égalité, au mérite ou à la solidarité. L’égalité des droits est une condition fondamentale, mais elle ne garantit pas à elle seule une égalité réelle des chances lorsque les individus disposent de ressources de départ très différentes.',
'John Rawls propose de juger les institutions à partir de principes choisis dans une situation hypothétique d’impartialité : libertés fondamentales égales, égalité équitable des chances et principe de différence. Ce dernier autorise certaines inégalités si elles améliorent la situation des plus désavantagés.',
'La redistribution peut être verticale, lorsqu’elle réduit les écarts de ressources, ou horizontale, lorsqu’elle mutualise les risques sociaux. Elle passe par les prélèvements, les prestations et les services publics ; son évaluation doit considérer ses effets sur la pauvreté, les inégalités, l’accès aux droits et les incitations.']]);

if(library['ses:environnement']) library['ses:environnement'].sections.push(['Approfondissement — mécanismes et enjeux',['Le climat et la biodiversité illustrent des problèmes d’action collective : les bénéfices de la protection sont partagés, tandis que les coûts de réduction des pollutions sont souvent supportés par des acteurs identifiables. Les externalités négatives conduisent à une production ou une consommation excessive lorsque les coûts sociaux ne sont pas intégrés aux décisions privées.',
'La réglementation impose des seuils ou des interdictions ; la taxe environnementale donne un prix à la pollution ; le marché de quotas fixe un plafond global et permet l’échange de droits. Le choix dépend de la nature du problème, de l’information disponible, de la capacité de contrôle et de l’acceptabilité sociale.',
'La coopération internationale est nécessaire lorsque les dommages dépassent les frontières, mais elle est difficile en raison des écarts de richesse, de responsabilité historique et de capacité d’action. Une politique efficace doit aussi traiter ses effets distributifs et accompagner les ménages et territoires les plus exposés.']]);

if(library['philo:art']) library['philo:art'].sections.push(['Approfondissement — mécanismes et enjeux',['Il faut distinguer la valeur esthétique, la valeur morale, la valeur marchande et la fonction sociale d’une œuvre. Une œuvre peut avoir une grande importance artistique sans être belle au sens classique, et son prix ne constitue pas une preuve de sa qualité esthétique.',
'La création met en jeu des règles et leur dépassement : la maîtrise technique rend possible l’œuvre, mais l’invention ne se réduit pas à l’application d’une recette. Le jugement de goût est subjectif dans son point de départ, tout en prétendant souvent pouvoir être partagé et discuté.']]);

if(library['philo:bonheur']) library['philo:bonheur'].sections.push(['Approfondissement — mécanismes et enjeux',['Le bonheur se distingue du plaisir ponctuel : il désigne généralement un état plus durable ou une manière de juger l’ensemble de son existence. Il faut aussi le distinguer de la joie, qui peut être intense mais passagère, et du bien-être, notion souvent liée aux conditions de vie.',
'Épicure distingue les désirs naturels et nécessaires des désirs vains ; la maîtrise des désirs peut conduire à la tranquillité. À l’inverse, une conception du bonheur comme accomplissement peut insister sur l’action, les relations et la réalisation de soi plutôt que sur la seule absence de douleur.']]);

if(library['philo:conscience']) library['philo:conscience'].sections.push(['Approfondissement — mécanismes et enjeux',['La conscience psychologique désigne la présence à ses pensées et à ses perceptions ; la conscience morale permet de juger ses actes. Ces deux sens sont liés mais ne se confondent pas : être conscient de ce que l’on fait ne signifie pas nécessairement savoir si l’action est juste.',
'La conscience donne un accès privilégié à l’expérience vécue, mais elle ne garantit pas une connaissance complète de soi. Les habitudes, les passions, les intérêts et les mécanismes inconscients peuvent limiter la transparence du sujet à lui-même.']]);

if(library['philo:devoir']) library['philo:devoir'].sections.push(['Approfondissement — mécanismes et enjeux',['Le devoir se distingue de la contrainte extérieure : une action peut être conforme à une règle par peur d’une sanction sans être accomplie par devoir. La question morale porte donc aussi sur le motif de l’action et sur la possibilité de reconnaître une obligation comme légitime.',
'Chez Kant, la valeur morale ne dépend pas seulement des conséquences avantageuses d’une action : elle tient à la maxime et à la possibilité de vouloir sa règle comme loi universelle. Cette exigence conduit à distinguer agir conformément au devoir et agir par devoir.']]);

if(library['philo:etat']) library['philo:etat'].sections.push(['Approfondissement — mécanismes et enjeux',['L’État se distingue du gouvernement : les gouvernements changent, tandis que les institutions et la continuité juridique de l’État demeurent. Il faut également distinguer pouvoir politique, autorité légitime et simple rapport de force.',
'La souveraineté désigne le pouvoir suprême dans un ordre politique, mais elle peut être limitée par le droit, les constitutions, les contre-pouvoirs et les engagements internationaux. La question centrale est de savoir comment rendre le pouvoir légitime tout en empêchant l’arbitraire.']]);

if(library['philo:inconscient']) library['philo:inconscient'].sections.push(['Approfondissement — mécanismes et enjeux',['L’inconscient psychique désigne des processus qui influencent la pensée et le comportement sans être présents à la conscience. Il invite à nuancer l’idée d’un sujet parfaitement transparent à lui-même, mais ne signifie pas que toute action serait dépourvue de responsabilité.',
'La psychanalyse freudienne interprète certains rêves, lapsus et symptômes comme des expressions indirectes de conflits psychiques. Cette théorie doit être présentée comme une approche particulière de l’inconscient, et non comme une preuve que chaque comportement aurait une signification cachée unique.']]);

if(library['philo:justice']) library['philo:justice'].sections.push(['Approfondissement — mécanismes et enjeux',['La justice peut désigner une institution qui applique le droit, une vertu qui consiste à respecter autrui, ou un idéal de répartition équitable. Une décision légale n’est pas automatiquement perçue comme juste : le droit positif peut être discuté à partir de principes moraux.',
'L’égalité de traitement ne signifie pas toujours traiter chacun de manière identique. L’équité peut exiger de tenir compte de différences de situation, à condition que les critères utilisés soient justifiables et compatibles avec les droits fondamentaux.']]);

if(library['philo:langage']) library['philo:langage'].sections.push(['Approfondissement — mécanismes et enjeux',['Le langage est un système de signes permettant de communiquer, de représenter et de structurer l’expérience. Il ne sert pas seulement à transmettre une pensée déjà constituée : les mots permettent aussi de classer, de distinguer et de rendre certaines idées partageables.',
'Il faut distinguer langage, langue et parole : la langue est un système partagé de signes et de règles, tandis que la parole est son usage concret. Les ambiguïtés, les métaphores et les contextes montrent que le sens ne se réduit pas à la définition du dictionnaire.']]);

if(library['philo:liberte']) library['philo:liberte'].sections.push(['Approfondissement — mécanismes et enjeux',['La liberté politique — disposer de droits et ne pas subir l’arbitraire — se distingue de la liberté morale, qui concerne l’autonomie de la volonté. La liberté d’action peut être empêchée par des obstacles extérieurs, tandis que la question du libre arbitre porte sur la capacité de choisir.',
'Le déterminisme affirme que les phénomènes ont des causes ; il ne suffit pas à conclure que toute action humaine serait prévisible ou que la responsabilité disparaîtrait. Comprendre les déterminations sociales, psychologiques et matérielles peut au contraire aider à élargir les possibilités d’action.']]);

if(library['philo:nature']) library['philo:nature'].sections.push(['Approfondissement — mécanismes et enjeux',['La nature peut désigner l’ensemble du monde non humain, ce qui existe indépendamment de l’intervention humaine, ou l’essence supposée d’une chose. Il faut distinguer nature et culture sans les opposer trop simplement : les humains transforment leur environnement et sont eux-mêmes façonnés par des milieux sociaux.',
'La technique permet de transformer la nature pour satisfaire des besoins, mais cette puissance pose la question des limites et de la responsabilité. La protection de l’environnement oblige à réfléchir à la valeur du vivant et aux conséquences à long terme des activités humaines.']]);

if(library['philo:raison']) library['philo:raison'].sections.push(['Approfondissement — mécanismes et enjeux',['La raison peut désigner la faculté de former des jugements, d’enchaîner des arguments et de distinguer le vrai du faux. Elle se manifeste dans la démonstration, mais aussi dans la délibération pratique : choisir des moyens et examiner les fins.',
'Il faut distinguer rationalité et rationalisation : un discours peut paraître cohérent tout en reposant sur des prémisses fausses ou des intérêts dissimulés. La raison exige donc l’examen des arguments, des preuves et des conditions de validité.']]);

if(library['philo:religion']) library['philo:religion'].sections.push(['Approfondissement — mécanismes et enjeux',['La religion associe généralement croyances, rites, récits et communautés. Elle ne se réduit pas à une opinion privée : elle peut organiser des pratiques collectives et proposer une interprétation du monde, de l’existence et de la mort.',
'La foi et la raison ne répondent pas nécessairement aux mêmes exigences de justification. Le débat philosophique porte sur la possibilité de concilier croyance et examen critique, mais aussi sur la place de la religion dans l’espace public et la liberté de conscience.']]);

if(library['philo:science']) library['philo:science'].sections.push(['Approfondissement — mécanismes et enjeux',['La science ne se définit pas seulement par l’accumulation de faits : elle construit des problèmes, formule des hypothèses, utilise des méthodes et soumet ses résultats à la critique. Une connaissance scientifique est justifiée par des procédures contrôlables et révisables.',
'Popper insiste sur la réfutabilité des théories : une proposition scientifique doit pouvoir être confrontée à des tests susceptibles de la mettre en défaut. Cela ne signifie pas que toute théorie est immédiatement abandonnée à la première difficulté, mais que la recherche organise la discussion critique des résultats.']]);

if(library['philo:technique']) library['philo:technique'].sections.push(['Approfondissement — mécanismes et enjeux',['La technique désigne des procédés et des outils orientés vers une transformation efficace du réel. Elle se distingue de la science, qui cherche d’abord à connaître et expliquer, même si les deux domaines se nourrissent mutuellement.',
'Le progrès technique peut accroître les capacités humaines, améliorer la santé et transformer le travail, mais il crée aussi des dépendances et des risques. La question n’est donc pas seulement de savoir ce qui est techniquement possible, mais ce qui est souhaitable et sous quelles règles collectives.']]);

if(library['philo:temps']) library['philo:temps'].sections.push(['Approfondissement — mécanismes et enjeux',['Il faut distinguer le temps mesuré par les horloges, la durée vécue et le temps historique. Une même durée objective peut sembler longue ou courte selon l’expérience ; le passé, le présent et l’avenir structurent aussi la mémoire et les projets.',
'Le temps pose la question du changement et de l’identité : comment une chose peut-elle demeurer elle-même tout en se transformant ? La conscience du temps relie mémoire, attention et anticipation, mais elle rappelle aussi la finitude de l’existence.']]);

if(library['philo:travail']) library['philo:travail'].sections.push(['Approfondissement — mécanismes et enjeux',['Le travail peut être une nécessité pour satisfaire les besoins, une activité de transformation du monde et une source d’identité ou de reconnaissance. Il peut émanciper en donnant des compétences et une autonomie, mais aussi aliéner lorsque le travailleur ne maîtrise ni le sens ni les conditions de son activité.',
'Il faut distinguer la valeur économique du travail, son utilité sociale et son sens pour celui qui l’accomplit. Les transformations techniques et l’organisation du travail posent la question du partage des tâches, de la reconnaissance et de la place du travail dans l’existence.']]);

if(library['philo:verite']) library['philo:verite'].sections.push(['Approfondissement — mécanismes et enjeux',['La vérité se distingue de la certitude subjective : être convaincu ne suffit pas à établir qu’une proposition est vraie. Il faut également distinguer vérité, sincérité et véracité : on peut se tromper sincèrement, ou dire quelque chose de vrai sans être sincère.',
'La recherche de la vérité suppose des critères adaptés aux domaines : cohérence logique, preuves empiriques, démonstration ou confrontation des témoignages. Le doute peut être une étape de la connaissance lorsqu’il permet de suspendre un jugement trop rapide et d’examiner ses raisons.']]);
